function sniffMime(buf){if(!buf||!buf.length)return 'application/octet-stream';if(buf.slice(0,4).toString('hex')==='25504446')return 'application/pdf';if(buf[0]===0xFF&&buf[1]===0xD8&&buf[2]===0xFF)return 'image/jpeg';if(buf.slice(0,8).toString('hex')==='89504e470d0a1a0a')return 'image/png';if(buf.slice(0,4).toString('hex')==='52494646'&&buf.slice(8,12).toString('ascii')==='WEBP')return 'image/webp';if(buf.slice(0,2).toString()==='PK')return 'application/zip-container';if(/^([\t\r\n -~])+$/.test(buf.slice(0,Math.min(buf.length,512)).toString('utf8')))return 'text/plain';return 'application/octet-stream'}
function multipartSingle(fieldName){return (req,res,next)=>{const ct=String(req.headers['content-type']||'');if(!ct.startsWith('multipart/form-data'))return next();const m=ct.match(/boundary=(?:\"([^\"]+)\"|([^;]+))/i);if(!m)return res.status(400).json({error:'Invalid multipart boundary'});const boundary=Buffer.from('--'+(m[1]||m[2]));const chunks=[];let total=0;req.on('data',c=>{total+=c.length;if(total>16*1024*1024){req.destroy();return}chunks.push(c)});req.on('end',()=>{try{const body=Buffer.concat(chunks);req.body=req.body||{};req.file=null;let pos=0;while((pos=body.indexOf(boundary,pos))!==-1){pos+=boundary.length;if(body.slice(pos,pos+2).toString()==='--')break;if(body.slice(pos,pos+2).toString()==='\r\n')pos+=2;const headEnd=body.indexOf(Buffer.from('\r\n\r\n'),pos);if(headEnd<0)break;const headers=body.slice(pos,headEnd).toString('utf8');const nextBoundary=body.indexOf(boundary,headEnd+4);if(nextBoundary<0)break;let contentEnd=nextBoundary-2;if(body[contentEnd]===13&&body[contentEnd+1]===10){}else contentEnd=nextBoundary;const content=body.slice(headEnd+4,contentEnd);const name=(headers.match(/name=\"([^\"]+)\"/i)||[])[1];const filename=(headers.match(/filename=\"([^\"]*)\"/i)||[])[1];const type=(headers.match(/Content-Type:\s*([^\r\n]+)/i)||[])[1]||'application/octet-stream';if(filename!==undefined){if(name!==fieldName){}else{if(content.length>15*1024*1024)throw new Error('File exceeds the 15 MB upload limit');if(!allowedUploadTypes.has(type))throw new Error('Unsupported document type. Use PDF, JPG, PNG, WEBP, TXT, CSV, DOCX or XLSX.');const detected=sniffMime(content);const office=type.includes('officedocument')&&detected==='application/zip-container';const textType=type==='text/plain'||type==='text/csv';if(!(detected===type||office||textType))throw new Error('File content does not match the declared document type.');req.file={originalname:filename||'document',mimetype:type,size:content.length,buffer:content};}}else if(name)req.body[name]=content.toString('utf8');pos=nextBoundary;}next()}catch(e){res.status(400).json({error:e.message})}});req.on('error',e=>next(e));};}

