function apiRateLimit(req,res,next){const key=`${req.ip}:${req.path.split('/').slice(0,3).join('/')}`;const now=Date.now();const v=apiBurst.get(key)||{count:0,resetAt:now+60000};if(v.resetAt<=now){v.count=0;v.resetAt=now+60000;}if(v.count>=120)return res.status(429).json({error:'Too many requests. Please try again shortly.',requestId:req.reqId});v.count++;apiBurst.set(key,v);next()}
