function base32Encode(buf){const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';let bits=0,value=0,out='';for(const b of buf){value=(value<<8)|b;bits+=8;while(bits>=5){out+=alphabet[(value>>(bits-5))&31];bits-=5}}if(bits>0)out+=alphabet[(value<<(5-bits))&31];return out}
function base32Decode(str){const alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';let bits=0,value=0,out=[];for(const c of String(str).toUpperCase().replace(/=+$/,'')){const i=alphabet.indexOf(c);if(i<0)continue;value=(value<<5)|i;bits+=5;if(bits>=8){out.push((value>>(bits-8))&255);bits-=8}}return Buffer.from(out)}
function totp(secret,step=Math.floor(Date.now()/1000/30)){const key=base32Decode(secret);const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(step));const h=crypto.createHmac('sha1',key).update(b).digest();const off=h[h.length-1]&15;const n=((h[off]&127)<<24)|((h[off+1]&255)<<16)|((h[off+2]&255)<<8)|(h[off+3]&255);return String(n%1000000).padStart(6,'0')}
function verifyTotp(secret,code){const c=String(code||'').replace(/\s/g,'');for(let d=-1;d<=1;d++)if(totp(secret,Math.floor(Date.now()/1000/30)+d)===c)return true;return false}
function encryptSecret(text){const key=crypto.createHash('sha256').update(JWT_SECRET||'').digest();const iv=crypto.randomBytes(12);const cipher=crypto.createCipheriv('aes-256-gcm',key,iv);const enc=Buffer.concat([cipher.update(text,'utf8'),cipher.final()]);return [iv.toString('base64url'),cipher.getAuthTag().toString('base64url'),enc.toString('base64url')].join('.')}
function decryptSecret(value){const [iv,tag,data]=String(value).split('.');const key=crypto.createHash('sha256').update(JWT_SECRET||'').digest();const decipher=crypto.createDecipheriv('aes-256-gcm',key,Buffer.from(iv,'base64url'));decipher.setAuthTag(Buffer.from(tag,'base64url'));return Buffer.concat([decipher.update(Buffer.from(data,'base64url')),decipher.final()]).toString('utf8')}
function deviceHash(deviceId){return crypto.createHash('sha256').update(String(deviceId||'' )+'|'+(JWT_SECRET||'')).digest('hex')}
