async function sendResendEmail({to,subject,html,text,userId,purpose}){
  const apiKey=String(process.env.RESEND_API_KEY||'');
  const from=String(process.env.EMAIL_FROM||'');
  if(!apiKey||!from){
    await pool.query('INSERT INTO email_delivery_logs(user_id,email,purpose,status,error_message) VALUES($1,$2,$3,$4,$5)',[userId||null,to,purpose,'Skipped','Resend is not configured yet (RESEND_API_KEY and EMAIL_FROM are required).']);
    return {sent:false,configured:false};
  }
  try{
    const response=await fetch('https://api.resend.com/emails',{method:'POST',headers:{Authorization:`Bearer ${apiKey}`,'Content-Type':'application/json'},body:JSON.stringify({from,to:[to],subject,html,text})});
    const data=await response.json().catch(()=>({}));
    if(!response.ok)throw new Error(data?.message||data?.error||`Resend returned ${response.status}`);
    await pool.query('INSERT INTO email_delivery_logs(user_id,email,purpose,status,provider_message_id) VALUES($1,$2,$3,$4,$5)',[userId||null,to,purpose,'Sent',String(data?.id||'')]);
    return {sent:true,configured:true,id:data?.id||null};
  }catch(e){
    await pool.query('INSERT INTO email_delivery_logs(user_id,email,purpose,status,error_message) VALUES($1,$2,$3,$4,$5)',[userId||null,to,purpose,'Failed',String(e.message||e)]);
    return {sent:false,configured:true,error:String(e.message||e)};
  }
}
