function stripPublicSensitive(value){
  const blocked=/^(id|.*_id|.*cost.*|purchase.*|supplier.*|warehouse.*|serial.*|imei.*|barcode|qr.*|internal.*|tax_rate|promotion_id|promotion_name)$/i;
  if(Array.isArray(value))return value.map(stripPublicSensitive);
  if(value&&typeof value==='object'){const out={};for(const [k,v] of Object.entries(value)){if(blocked.test(k))continue;out[k]=stripPublicSensitive(v)}return out;}
  return value;
}

app.get('/api/public/catalog',async(req,res)=>{
  try{
    const [categories,brands,products,collections]=await Promise.all([
      q(`SELECT pc.id,pc.name,pc.slug,pc.description,pc.image_url,pc.banner_url,pc.icon_url,pc.featured,pc.sort_order,parent.slug parent_slug FROM product_categories pc LEFT JOIN product_categories parent ON parent.id=pc.parent_id WHERE pc.status='Active' AND pc.website_visibility='Published' ORDER BY pc.sort_order,pc.name`),
      q(`SELECT id,name,slug,description,logo_url,image_url,banner_url,featured,sort_order FROM brands WHERE status='Active' AND website_visibility='Published' ORDER BY sort_order,name`),
      q(`SELECT p.id,p.name,p.slug,p.product_type,p.short_description,p.description,p.specifications,p.featured,b.name brand_name,b.slug brand_slug,c.name category_name,c.slug category_slug,(SELECT json_agg(json_build_object('code',v.sku,'name',v.variant_name,'colour',v.color,'storage',v.storage,'size',v.size,'sellingPrice',v.selling_price,'compareAtPrice',v.compare_at_price,'inStock',CASE WHEN v.track_inventory THEN COALESCE((SELECT SUM(ib.on_hand-ib.reserved) FROM inventory_balances ib WHERE ib.variant_id=v.id),0)>0 ELSE true END) ORDER BY v.sku) FROM product_variants v WHERE v.product_id=p.id AND v.status='Active') variants,
      (SELECT json_agg(json_build_object('key',a.attribute_key,'value',a.attribute_value,'unit',a.unit,'sortOrder',a.sort_order) ORDER BY a.sort_order,a.attribute_key) FROM product_attributes a WHERE a.product_id=p.id AND a.searchable=true AND a.active=true) attributes,(SELECT json_agg(json_build_object('url',CONCAT('/api/public/media/',m.id,'/file?v=',m.checksum_sha256),'altText',i.alt_text,'primary',i.is_primary,'sortOrder',i.sort_order) ORDER BY i.is_primary DESC,i.sort_order,i.created_at) FROM product_images i JOIN media_assets m ON m.id=i.media_id AND m.status='Active' AND m.visibility='Public' WHERE i.product_id=p.id) images FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN product_categories c ON c.id=p.category_id WHERE p.status='Active' AND p.website_visibility='Published' ORDER BY p.featured DESC,p.updated_at DESC`),
      q(`SELECT c.id,c.name,c.slug,c.description,c.image_url,c.featured,c.sort_order,COALESCE((SELECT json_agg(json_build_object('id',p.id,'name',p.name,'slug',p.slug,'brand',b.name,'category',pc.name) ORDER BY cp.sort_order,p.name) FROM catalog_collection_products cp JOIN products p ON p.id=cp.product_id LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN product_categories pc ON pc.id=p.category_id WHERE cp.collection_id=c.id AND p.status='Active' AND p.website_visibility='Published'),'[]'::json) products FROM catalog_collections c WHERE c.status='Active' AND c.website_visibility='Published' ORDER BY c.sort_order,c.name`)
    ]);
    res.json(stripPublicSensitive({updatedAt:new Date().toISOString(),categories,brands,products,collections}));
  }catch(e){res.status(503).json({error:'Public catalogue is temporarily unavailable.'})}
});

app.post('/api/setup',async(req,res)=>{
  const lock=await q("SELECT pg_try_advisory_lock(hashtext('amaal_initial_setup')) AS locked");
  if(!lock[0].locked)return res.status(409).json({error:'Initial setup is already in progress'});
  const client=await pool.connect();
  try{
    const activeAdmins=await client.query("SELECT count(*)::int c FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.status='Active' AND r.name='Super Admin'").then(r=>r.rows[0].c);
    const setupFlag=safeJson((await client.query("SELECT value_json FROM settings WHERE key='administratorSetupRequired'")).rows[0]?.value_json);
    if(activeAdmins>0&&!Boolean(setupFlag))return res.status(409).json({error:'Administrator already configured'});
    const {companyName='Amaal Telecoms',email,password,phone='',address=''}=req.body||{};
    const normalized=String(email||'').toLowerCase().trim();
    const policy=Object.fromEntries(Object.entries(baseSettings).filter(([k])=>k.startsWith('password')));
    const pErr=passwordError(password,policy);
    if(!normalized||pErr)return res.status(400).json({error:pErr||'Email is required'});
    await client.query('BEGIN');
    const role=(await client.query("SELECT id FROM roles WHERE name='Super Admin'")).rows[0];
    if(!role)throw new Error('Super Admin role is missing. Restart the service so the database schema/bootstrap can finish.');
    const existingByEmail=(await client.query('SELECT * FROM users WHERE email=$1 FOR UPDATE',[normalized])).rows[0];
    const hash=await bcrypt.hash(password,12);
    let u;
    if(existingByEmail){
      if(existingByEmail.status!=='Suspended')throw new Error('An administrator account with this email is already active. Use another email or complete administrator recovery first.');
      u=(await client.query(`UPDATE users SET name='Administrator',password_hash=$1,status='Active',failed_attempts=0,locked_until=NULL,last_login_at=NULL,mfa_enabled=false,phone=$2,updated_at=now(),updated_by=NULL WHERE id=$3 RETURNING id,name,email,status,created_at`,[hash,phone,existingByEmail.id])).rows[0];
      await client.query('DELETE FROM user_roles WHERE user_id=$1',[u.id]);
      await client.query('DELETE FROM user_branches WHERE user_id=$1',[u.id]);
      await client.query('DELETE FROM mfa_credentials WHERE user_id=$1',[u.id]);
    }else{
      u=(await client.query('INSERT INTO users(name,email,password_hash) VALUES($1,$2,$3) RETURNING id,name,email,status,created_at',['Administrator',normalized,hash])).rows[0];
    }
    await client.query('INSERT INTO user_roles(user_id,role_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[u.id,role.id]);
    for(const [k,v] of Object.entries({...baseSettings,companyName,companyEmail:u.email,companyPhone:phone,companyAddress:address})) await client.query('INSERT INTO settings(key,value_json) VALUES($1,$2) ON CONFLICT(key) DO UPDATE SET value_json=EXCLUDED.value_json,updated_at=now(),updated_by=NULL',[k,JSON.stringify(v)]);
    await client.query("UPDATE organizations SET legal_name=$1,trading_name=$1,email=$2,phone=$3,address=$4,updated_at=now(),updated_by=NULL WHERE id=(SELECT id FROM organizations ORDER BY created_at LIMIT 1)",[companyName,u.email,phone,address]);
    await client.query("INSERT INTO settings(key,value_json) VALUES('administratorSetupRequired','false') ON CONFLICT(key) DO UPDATE SET value_json='false'::jsonb,updated_at=now(),updated_by=$1",[u.id]);
    await client.query("INSERT INTO password_history(user_id,password_hash) VALUES($1,$2)",[u.id,hash]);
    const deviceId=getOrCreateDeviceId(req);
    const dHash=deviceHash(deviceId);
    await client.query('INSERT INTO trusted_devices(user_id,device_hash,label,last_ip,user_agent) VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id,device_hash) DO UPDATE SET last_seen_at=now(),last_ip=EXCLUDED.last_ip,user_agent=EXCLUDED.user_agent,revoked_at=NULL',[u.id,dHash,'Initial setup device',req.ip,req.get('user-agent')||'']);
    const sid=crypto.randomUUID();
    await client.query("INSERT INTO sessions(id,user_id,token_hash,device_hash,user_agent_hash,expires_at,ip,user_agent) VALUES($1,$2,$3,$4,$5,now()+($6 || ' minutes')::interval,$7,$8)",[sid,u.id,crypto.createHash('sha256').update(sid+JWT_SECRET).digest('hex'),dHash,userAgentHash(req.get('user-agent')),Number(baseSettings.sessionMinutes),req.ip,req.get('user-agent')]);
    await client.query('COMMIT');
    await audit(u,'INITIAL_SETUP','System',null,existingByEmail?'Reactivated the recovered administrator account':'Created the first administrator',null,{email:u.email});
    setAuthCookie(res,sign(u,sid),Number(baseSettings.sessionMinutes)*60,deviceId);
    res.setHeader('Cache-Control','no-store, max-age=0');
    res.json({user:u,recoveredExistingAccount:Boolean(existingByEmail)});
  }catch(e){
    try{await client.query('ROLLBACK')}catch{}
    const msg=String(e?.message||'Initial setup failed');
    console.error('Initial setup failed:',e);
    res.status(msg.includes('already active')?409:400).json({error:msg});
  }finally{
    client.release();
    await pool.query("SELECT pg_advisory_unlock(hashtext('amaal_initial_setup'))");
  }
});
app.get('/api/setup/status',async(req,res)=>{try{const users=(await q("SELECT count(*)::int c FROM users WHERE status='Active'"))[0].c;const superAdmins=(await q("SELECT count(*)::int c FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.status='Active' AND r.name='Super Admin'"))[0].c;const flag=safeJson((await q("SELECT value_json FROM settings WHERE key='administratorSetupRequired'"))[0]?.value_json);const configured=superAdmins>0&&!Boolean(flag);res.setHeader('Cache-Control','no-store, max-age=0');res.json({configured,setupRequired:!configured,activeUsers:users,superAdmins})}catch(e){console.error('Setup status failed',e);res.status(503).json({error:'Database unavailable'})}});

// One-time, explicitly enabled administrator recovery. Keep ADMIN_RECOVERY_TOKEN out of source control.
function safeTokenEqual(a,b){const aa=Buffer.from(String(a||''));const bb=Buffer.from(String(b||''));return aa.length===bb.length&&aa.length>0&&crypto.timingSafeEqual(aa,bb)}
app.get('/recovery',(_req,res)=>{
  const enabled=Boolean(process.env.ADMIN_RECOVERY_TOKEN);
  const state=enabled
    ? '<div id=state class="status ok">Recovery is enabled. Enter the recovery token and type AMAAL-RESET to continue.</div>'
    : '<div id=state class="status">Recovery is currently disabled. Add ADMIN_RECOVERY_TOKEN in Render Environment and redeploy.</div>';
  const formArea=enabled
    ? '<div id=formarea><label>Recovery token<input name=token type=password required autocomplete=off></label><label>Confirmation<input name=confirm placeholder="AMAAL-RESET" required autocomplete=off></label><button type=submit>Reset administrator access</button></div>'
    : '<div id=formarea style="display:none"></div>';
  res.type('html').send(`<!doctype html><html><head><meta name=viewport content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Amaal Telecoms · Administrator Recovery</title><style>*{box-sizing:border-box}body{font-family:system-ui,-apple-system,sans-serif;background:#0b1220;color:#0f172a;margin:0;padding:20px;min-height:100vh;display:grid;place-items:center}.box{width:min(500px,100%);background:#fff;border-radius:24px;padding:28px;box-shadow:0 30px 80px #0008}.brand{font-size:13px;font-weight:900;letter-spacing:.12em;color:#475569;text-transform:uppercase}.warn{background:#fff7ed;color:#9a3412;padding:14px;border-radius:14px;margin:16px 0;line-height:1.5}label{display:block;font-weight:700;margin-top:14px}input,button{font:inherit;width:100%;padding:13px 14px;border-radius:12px;margin-top:7px}input{border:1px solid #cbd5e1}button{border:0;background:#111827;color:#fff;font-weight:800;cursor:pointer}button:disabled{opacity:.6;cursor:wait}.status{padding:12px;border-radius:12px;margin-top:12px;background:#f1f5f9;color:#334155}.bad{background:#fef2f2;color:#991b1b}.ok{background:#ecfdf5;color:#166534}.small{font-size:13px;color:#64748b;line-height:1.5}code{background:#f1f5f9;padding:2px 5px;border-radius:5px}</style></head><body><form class=box id=f><div class=brand>Amaal Telecoms · Security</div><h1>Administrator recovery</h1><p class=small>Use this only when normal administrator access is unavailable. Business records are preserved.</p><div class=warn><b>Important:</b> recovery revokes administrator sessions and trusted devices, suspends active accounts, and preserves MFA credentials, password history, role links, notifications, audit history and business records, and suspends existing administrator accounts. It does not delete products, sales, inventory, customers, orders, finance or other business records.</div>${state}${formArea}<p class=small>If recovery is not enabled, set <code>ADMIN_RECOVERY_TOKEN</code> in Render Environment and redeploy. Never put that secret in GitHub.</p><div id=msg></div></form><script src="/recovery.js" defer></script></body></html>`)
})
app.get('/api/recovery/status',(_req,res)=>res.json({enabled:Boolean(process.env.ADMIN_RECOVERY_TOKEN),serverTime:new Date().toISOString()}));
app.post('/api/recovery/reset',async(req,res)=>{
  const configured=String(process.env.ADMIN_RECOVERY_TOKEN||'');
  if(!rateWindow(resetAttempts,'admin-recovery:'+req.ip,5,15*60*1000))return res.status(429).json({error:'Too many recovery attempts. Please wait before trying again.'});
  if(!configured)return res.status(404).json({error:'Recovery is disabled. Set ADMIN_RECOVERY_TOKEN in the deployment environment and redeploy.'});
  const token=String(req.body?.token||'');
  if(!safeTokenEqual(token,configured))return res.status(403).json({error:'Invalid recovery token'});
  if(String(req.body?.confirm||'')!=='AMAAL-RESET')return res.status(400).json({error:'Type AMAAL-RESET to confirm'});
  const tokenHash=crypto.createHash('sha256').update(configured).digest('hex');
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const used=(await client.query("SELECT value_json FROM settings WHERE key='adminRecoveryTokenHash'")).rows[0];
    const flag=safeJson((await client.query("SELECT value_json FROM settings WHERE key='administratorSetupRequired'")).rows[0]?.value_json);
    if(safeJson(used?.value_json)===tokenHash && Boolean(flag)){
      await client.query("INSERT INTO settings(key,value_json) VALUES('administratorSetupRequired','true') ON CONFLICT(key) DO UPDATE SET value_json='true'::jsonb,updated_at=now(),updated_by=NULL");
      await client.query('COMMIT');
      clearAuthCookie(res);
      return res.json({ok:true,alreadyReset:true,accountsSuspended:0,auditEvents:0,message:'Administrator recovery is already complete. First-time administrator setup is enabled.'});
    }
    if(safeJson(used?.value_json)===tokenHash && !Boolean(flag))return res.status(409).json({error:'This recovery token has already been used. Rotate ADMIN_RECOVERY_TOKEN before another recovery.'});

    // Recovery never deletes users. Historical user rows may be referenced by
    // business records, so deletion is both unsafe and unnecessary. We revoke
    // all authentication state and suspend every administrator account. The
    // setup endpoint can then safely reclaim the same email or create a new one.
    await client.query("UPDATE sessions SET revoked_at=now() WHERE revoked_at IS NULL");
    await client.query("UPDATE trusted_devices SET revoked_at=now() WHERE revoked_at IS NULL");
    const suspended=(await client.query("UPDATE users SET status='Suspended',failed_attempts=0,locked_until=NULL,updated_at=now(),updated_by=NULL WHERE status='Active' RETURNING id")).rowCount;
    await client.query("INSERT INTO settings(key,value_json) VALUES('administratorSetupRequired','true') ON CONFLICT(key) DO UPDATE SET value_json='true'::jsonb,updated_at=now(),updated_by=NULL");
    await client.query("INSERT INTO settings(key,value_json) VALUES('adminRecoveryTokenHash',$1) ON CONFLICT(key) DO UPDATE SET value_json=EXCLUDED.value_json,updated_at=now(),updated_by=NULL",[JSON.stringify(tokenHash)]);
    await client.query('COMMIT');
    clearAuthCookie(res);
    res.setHeader('Cache-Control','no-store, max-age=0');
    res.json({ok:true,accountsSuspended:suspended,auditEvents:0,accountsDeleted:false,message:'Administrator access has been reset. Business records were preserved. First-time administrator setup is now ready.'});
  }catch(e){try{await client.query('ROLLBACK')}catch{}console.error('Recovery reset failed',e);res.status(500).json({error:'Recovery failed. No changes were committed.'});}
  finally{client.release()}
});

app.post('/api/password/forgot',async(req,res)=>{
  if(!rateWindow(resetAttempts,req.ip,5,15*60*1000))return genericRecoveryResponse(res);
  const normalized=String(req.body?.email||'').toLowerCase().trim();
  if(!normalized||normalized.length>320)return genericRecoveryResponse(res);
  if(!rateWindow(resetAttempts,'email:'+normalized,5,60*60*1000))return genericRecoveryResponse(res);
  const rid=requestId();
  try{
    const u=(await q("SELECT id,name,email,status FROM users WHERE email=$1",[normalized]))[0];
    // Always return the same response to avoid account enumeration.
    if(!u||u.status!=='Active'){
      await pool.query('INSERT INTO email_delivery_logs(email,purpose,status,error_message) VALUES($1,$2,$3,$4)',[normalized,'password_reset','Skipped','No active account matched the requested address.']);
      return genericRecoveryResponse(res);
    }
    const recent=(await q("SELECT count(*)::int c FROM password_reset_tokens WHERE user_id=$1 AND created_at>now()-interval '1 hour'",[u.id]))[0].c;
    if(recent>=5)return genericRecoveryResponse(res);
    const raw=crypto.randomBytes(48).toString('base64url');
    const tokenHash=crypto.createHash('sha256').update(raw).digest('hex');
    await pool.query("UPDATE password_reset_tokens SET used_at=now() WHERE user_id=$1 AND used_at IS NULL",[u.id]);
    await pool.query("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at,requested_ip,user_agent) VALUES($1,$2,now()+interval '30 minutes',$3,$4)",[u.id,tokenHash,req.ip,req.get('user-agent')||'']);
    const link=`${appBaseUrl(req)}/password-reset.html?token=${encodeURIComponent(raw)}`;
    const mail=await sendResendEmail({userId:u.id,to:u.email,purpose:'password_reset',subject:'Amaal Telecoms password reset',text:`Hello ${u.name||'Administrator'},\n\nUse this link to reset your Amaal Telecoms password. It expires in 30 minutes and can only be used once:\n${link}\n\nIf you did not request this, you can ignore this email.`,html:`<p>Hello ${htmlEscape(u.name||'Administrator')},</p><p>We received a request to reset your Amaal Telecoms password.</p><p><a href="${htmlEscape(link)}">Reset your password</a></p><p>This link expires in 30 minutes and can only be used once.</p><p>If you did not request this, you can ignore this email.</p>`});
    await pool.query('INSERT INTO security_events(actor_id,event_type,severity,detail,ip,user_agent,request_id) VALUES($1,$2,$3,$4,$5,$6,$7)',[u.id,'PASSWORD_RESET_REQUESTED','info',mail.sent?'Password reset email sent':'Password reset requested; email delivery is not configured or failed',req.ip,req.get('user-agent')||'',rid]);
    await audit(null,'PASSWORD_RESET_REQUESTED','User',u.id,mail.sent?'Requested password reset and sent recovery email':'Requested password reset; delivery is pending configuration',null,{emailSent:mail.sent},{id:rid,ip:req.ip,ua:req.get('user-agent')});
    return genericRecoveryResponse(res);
  }catch(e){console.error('Password reset request failed',e);return genericRecoveryResponse(res);}
});
app.get('/api/password/reset/validate',async(req,res)=>{
  const raw=String(req.query?.token||'');
  if(raw.length<20)return res.status(400).json({valid:false,error:'Reset link is invalid or expired'});
  const hash=crypto.createHash('sha256').update(raw).digest('hex');
  const row=(await q("SELECT pr.expires_at,pr.used_at,u.email,u.name,u.status FROM password_reset_tokens pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=$1",[hash]))[0];
  const valid=Boolean(row&&row.status==='Active'&&!row.used_at&&new Date(row.expires_at)>new Date());
  if(!valid)return res.status(400).json({valid:false,error:'Reset link is invalid or expired'});
  res.setHeader('Cache-Control','no-store,max-age=0');
  res.json({valid:true,email:row.email,name:row.name,expiresAt:row.expires_at});
});
app.post('/api/password/reset',async(req,res)=>{
  const raw=String(req.body?.token||'');
  const newPassword=String(req.body?.newPassword||'');
  if(raw.length<20)return res.status(400).json({error:'Reset link is invalid or expired'});
  const tokenHash=crypto.createHash('sha256').update(raw).digest('hex');
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const row=(await client.query("SELECT pr.*,u.id user_id,u.name,u.email,u.status,u.password_hash FROM password_reset_tokens pr JOIN users u ON u.id=pr.user_id WHERE pr.token_hash=$1 FOR UPDATE",[tokenHash])).rows[0];
    if(!row||row.used_at||new Date(row.expires_at)<=new Date()||row.status!=='Active')throw new Error('Reset link is invalid or expired');
    const policy=Object.fromEntries((await client.query("SELECT key,value_json FROM settings WHERE key LIKE 'password%'" )).rows.map(x=>[x.key,safeJson(x.value_json)]));
    const pErr=passwordError(newPassword,policy);if(pErr)throw new Error(pErr);
    const history=(await client.query('SELECT password_hash FROM password_history WHERE user_id=$1 ORDER BY created_at DESC LIMIT 5',[row.user_id])).rows;
    for(const h of [row.password_hash,...history.map(x=>x.password_hash)])if(await bcrypt.compare(newPassword,h.password_hash))throw new Error('Do not reuse a recent password');
    const hash=await bcrypt.hash(newPassword,12);
    await client.query('UPDATE users SET password_hash=$1,failed_attempts=0,locked_until=NULL,updated_at=now() WHERE id=$2',[hash,row.user_id]);
    await client.query('INSERT INTO password_history(user_id,password_hash) VALUES($1,$2)',[row.user_id,hash]);
    await client.query('UPDATE password_reset_tokens SET used_at=now() WHERE id=$1',[row.id]);
    await client.query('UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND revoked_at IS NULL',[row.user_id]);
    await client.query('UPDATE trusted_devices SET revoked_at=now() WHERE user_id=$1 AND revoked_at IS NULL',[row.user_id]);
    await client.query('INSERT INTO security_events(actor_id,event_type,severity,detail,ip,user_agent,request_id) VALUES($1,$2,$3,$4,$5,$6,$7)',[row.user_id,'PASSWORD_RESET_COMPLETED','info','Password reset completed; active sessions and trusted devices were revoked',req.ip,req.get('user-agent')||'',requestId()]);
    await client.query('COMMIT');
    await audit(null,'PASSWORD_RESET_COMPLETED','User',row.user_id,'Completed password reset from a single-use recovery link',null,{userId:row.user_id}, {id:requestId(),ip:req.ip,ua:req.get('user-agent')});
    res.setHeader('Cache-Control','no-store,max-age=0');
    res.json({ok:true,message:'Password reset successfully. Please sign in again.'});
  }catch(e){try{await client.query('ROLLBACK')}catch{};res.status(400).json({error:String(e.message||'Password reset failed')});}
  finally{client.release();}
});

app.post('/api/login',async(req,res)=>{const ip=req.ip;const now=Date.now();const a=loginAttempts.get(ip)||{count:0,until:0};if(a.until>now)return res.status(429).json({error:'Too many sign-in attempts. Try again later.'});const {email,password,code}=req.body||{};const normalized=String(email||'').toLowerCase().trim();const u=(await q('SELECT * FROM users WHERE email=$1',[normalized]))[0];const rid=requestId();if(!u){a.count++;if(a.count>=8)a.until=now+15*60000;loginAttempts.set(ip,a);await pool.query('INSERT INTO login_events(email,success,reason,ip,user_agent,request_id) VALUES($1,false,$2,$3,$4,$5)',[normalized,'Invalid credentials',req.ip,req.get('user-agent'),rid]);return res.status(401).json({error:'Invalid credentials'})}if(u.status!=='Active')return res.status(403).json({error:'Account inactive'});if(u.locked_until&&new Date(u.locked_until)>new Date())return res.status(423).json({error:'Account temporarily locked'});const ok=await bcrypt.compare(password||'',u.password_hash);if(!ok){a.count++;if(a.count>=8)a.until=now+15*60000;loginAttempts.set(ip,a);const attempts=u.failed_attempts+1;const policy=await q("SELECT key,value_json FROM settings WHERE key = ANY($1)",[['maxLoginAttempts','lockoutMinutes']]);const po=Object.fromEntries(policy.map(x=>[x.key,safeJson(x.value_json)]));const limit=Number(po.maxLoginAttempts||5),minutes=Number(po.lockoutMinutes||15);const locked=attempts>=limit?new Date(Date.now()+minutes*60000):null;await pool.query('UPDATE users SET failed_attempts=$1,locked_until=$2,updated_at=now() WHERE id=$3',[attempts,locked,u.id]);await pool.query('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent,request_id) VALUES($1,$2,false,$3,$4,$5,$6)',[u.id,normalized,locked?'Account locked after failed attempts':'Invalid credentials',req.ip,req.get('user-agent'),rid]);return res.status(401).json({error:locked?'Too many attempts. Account temporarily locked.':'Invalid credentials'})}const mfaRequired=Boolean(safeJson((await q("SELECT value_json FROM settings WHERE key='mfaRequired'"))[0]?.value_json||false));const deviceId=getOrCreateDeviceId(req);const dHash=deviceHash(deviceId);const trusted=(await q('SELECT id FROM trusted_devices WHERE user_id=$1 AND device_hash=$2 AND revoked_at IS NULL',[u.id,dHash]))[0];const firstLogin=!u.last_login_at&&!trusted;const newDevice=!trusted&&!firstLogin;const mfaEnforced=MFA_LOGIN_ENABLED&&(mfaRequired||newDevice);if(mfaEnforced&&!u.mfa_enabled){if(newDevice)return res.status(403).json({error:'MFA is required before signing in from a new device. Sign in from a trusted device and enable MFA first.'});return res.status(403).json({error:'MFA is required for this account. Enable it before signing in.'})}if(mfaEnforced&&u.mfa_enabled){const row=(await q('SELECT secret_encrypted FROM mfa_credentials WHERE user_id=$1',[u.id]))[0];if(!row||!verifyTotp(decryptSecret(row.secret_encrypted),code)){a.count++;if(a.count>=8)a.until=now+15*60000;loginAttempts.set(ip,a);await pool.query('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent,request_id) VALUES($1,$2,false,$3,$4,$5,$6)',[u.id,normalized,'MFA verification failed',req.ip,req.get('user-agent'),rid]);return res.status(401).json({error:'Authenticator code required or invalid',codeRequired:true})}await pool.query('INSERT INTO trusted_devices(user_id,device_hash,label,last_ip,user_agent) VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id,device_hash) DO UPDATE SET last_seen_at=now(),last_ip=EXCLUDED.last_ip,user_agent=EXCLUDED.user_agent,revoked_at=NULL',[u.id,dHash,'Trusted device',req.ip,req.get('user-agent')||''])}else if(!trusted){await pool.query('INSERT INTO trusted_devices(user_id,device_hash,label,last_ip,user_agent) VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id,device_hash) DO UPDATE SET last_seen_at=now(),last_ip=EXCLUDED.last_ip,user_agent=EXCLUDED.user_agent,revoked_at=NULL',[u.id,dHash,'Trusted device',req.ip,req.get('user-agent')||''])}await pool.query('UPDATE users SET failed_attempts=0,locked_until=null,last_login_at=now() WHERE id=$1',[u.id]);const sessionMinutes=Number((await q("SELECT value_json FROM settings WHERE key='sessionMinutes'"))[0]?.value_json||720);const sid=crypto.randomUUID();await pool.query('INSERT INTO sessions(id,user_id,token_hash,device_hash,user_agent_hash,expires_at,ip,user_agent) VALUES($1,$2,$3,$4,$5,now()+($6 || \' minutes\')::interval,$7,$8)',[sid,u.id,crypto.createHash('sha256').update(sid+JWT_SECRET).digest('hex'),dHash,userAgentHash(req.get('user-agent')),sessionMinutes,req.ip,req.get('user-agent')]);await pool.query('INSERT INTO login_events(user_id,email,success,reason,ip,user_agent,request_id) VALUES($1,$2,true,$3,$4,$5,$6)',[u.id,normalized,newDevice?'Login successful after MFA new-device verification':'Login successful',req.ip,req.get('user-agent'),rid]);await audit(u,'LOGIN','Authentication',u.id,newDevice?'Administrator signed in with new trusted device':'Administrator signed in',null,null,{id:rid,ip:req.ip,ua:req.get('user-agent')});loginAttempts.delete(ip);setAuthCookie(res,sign(u,sid),sessionMinutes*60,deviceId);res.setHeader('Cache-Control','no-store, max-age=0');res.json({user:{id:u.id,name:u.name,email:u.email,status:u.status,mfaEnabled:u.mfa_enabled,mfaSetupRecommended:firstLogin&&!u.mfa_enabled}})});
