app.post('/api/invitations/accept',async(req,res)=>{
  const {token,password,name}=req.body||{};const hash=crypto.createHash('sha256').update(String(token||'')).digest('hex');
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    const i=(await client.query('SELECT * FROM invitations WHERE token_hash=$1 FOR UPDATE',[hash])).rows[0];
    if(!i||i.accepted_at||i.revoked_at||new Date(i.expires_at)<new Date())throw new Error('Invitation is invalid or expired');
    const policy=Object.fromEntries((await client.query("SELECT key,value_json FROM settings WHERE key LIKE 'password%'")).rows.map(x=>[x.key,safeJson(x.value_json)]));
    const pErr=passwordError(password,policy);if(pErr)throw new Error(pErr);
    const existing=(await client.query('SELECT id FROM users WHERE email=$1',[i.email])).rows[0];if(existing)throw new Error('An account already exists for this email');
    const hashPwd=await bcrypt.hash(password,12);
    const u=(await client.query('INSERT INTO users(name,email,password_hash,email_verified_at) VALUES($1,$2,$3,now()) RETURNING id,name,email,status,created_at,mfa_enabled',[String(name||i.name||i.email).trim(),i.email,hashPwd])).rows[0];
    if(i.role_id)await client.query('INSERT INTO user_roles(user_id,role_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[u.id,i.role_id]);
    await client.query('INSERT INTO password_history(user_id,password_hash) VALUES($1,$2)',[u.id,hashPwd]);
    const inviteDevice=getOrCreateDeviceId(req),dHash=deviceHash(inviteDevice),sid=crypto.randomUUID();
    await client.query('INSERT INTO trusted_devices(user_id,device_hash,label,last_ip,user_agent) VALUES($1,$2,$3,$4,$5) ON CONFLICT(user_id,device_hash) DO UPDATE SET last_seen_at=now(),last_ip=EXCLUDED.last_ip,user_agent=EXCLUDED.user_agent,revoked_at=NULL',[u.id,dHash,'Invitation acceptance device',req.ip,req.get('user-agent')||'']);
    const sessionMinutes=Number((await client.query("SELECT value_json FROM settings WHERE key='sessionMinutes'")).rows[0]?.value_json||720);
    await client.query("INSERT INTO sessions(id,user_id,token_hash,device_hash,user_agent_hash,expires_at,ip,user_agent) VALUES($1,$2,$3,$4,$5,now()+($6 || ' minutes')::interval,$7,$8)",[sid,u.id,crypto.createHash('sha256').update(sid+JWT_SECRET).digest('hex'),dHash,userAgentHash(req.get('user-agent')),sessionMinutes,req.ip,req.get('user-agent')||'']);
    await client.query('UPDATE invitations SET accepted_at=now() WHERE id=$1',[i.id]);
    await client.query('INSERT INTO security_events(actor_id,event_type,severity,detail,ip,user_agent,request_id) VALUES($1,$2,$3,$4,$5,$6,$7)',[u.id,'INVITATION_ACCEPTED','info','Accepted staff invitation',req.ip,req.get('user-agent')||'',requestId()]);
    await client.query('COMMIT');
    await audit(u,'INVITATION_ACCEPTED','Invitation',i.id,'Accepted staff invitation and created an active account',null,{userId:u.id,email:u.email},{id:requestId(),ip:req.ip,ua:req.get('user-agent')});
    setAuthCookie(res,sign(u,sid),sessionMinutes*60,inviteDevice);
    res.status(201).json({ok:true,user:u});
  }catch(e){try{await client.query('ROLLBACK')}catch{};res.status(400).json({error:String(e.message||'Invitation acceptance failed')});}
  finally{client.release();}
});
