app.patch('/api/users/:id/status',auth,need('staff.manage'),async(req,res)=>{const old=(await q('SELECT id,name,email,status FROM users WHERE id=$1',[req.params.id]))[0];if(!old)return res.status(404).json({error:'User not found'});if(old.id===req.user.id)return res.status(400).json({error:'You cannot suspend your own account'});if(!['Active','Suspended'].includes(req.body?.status))return res.status(400).json({error:'Status must be Active or Suspended'});const targetIsSuper=Boolean((await q("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 AND r.name='Super Admin' LIMIT 1",[old.id]))[0]);const actorIsSuper=Boolean((await q("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 AND r.name='Super Admin' LIMIT 1",[req.user.id]))[0]);if(targetIsSuper&&!actorIsSuper)return res.status(403).json({error:'Only a Super Admin can change another Super Admin account status'});if(targetIsSuper&&req.body.status==='Suspended'){const count=(await q("SELECT count(*)::int c FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.status='Active' AND r.name='Super Admin'"))[0].c;if(count<=1)return res.status(400).json({error:'At least one active Super Admin must remain'});}const u=(await q("UPDATE users SET status=$1,updated_at=now() WHERE id=$2 RETURNING id,name,email,status",[req.body.status,req.params.id]))[0];if(u.status==='Suspended'){await pool.query('UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND revoked_at IS NULL',[u.id]);await pool.query('UPDATE trusted_devices SET revoked_at=now() WHERE user_id=$1 AND revoked_at IS NULL',[u.id]);}await audit(req.user,'STAFF_STATUS_CHANGED','User',u.id,'Changed staff status; access sessions revoked when suspended',old,u,req.req);res.json(u)});
app.post('/api/users',auth,need('staff.manage'),async(req,res)=>{const {name,email,password,roleId,branchIds=[]}=req.body;const policy=Object.fromEntries((await q("SELECT key,value_json FROM settings WHERE key LIKE 'password%'")).map(x=>[x.key,safeJson(x.value_json)]));const pErr=passwordError(password,policy);if(!name||!email||pErr)return res.status(400).json({error:pErr||'Name and email are required'});if(roleId){const role=(await q('SELECT id,name FROM roles WHERE id=$1',[roleId]))[0];if(!role)return res.status(400).json({error:'Selected role does not exist'});if(role.name==='Super Admin'){const actorIsSuper=Boolean((await q("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 AND r.name='Super Admin' LIMIT 1",[req.user.id]))[0]);if(!actorIsSuper)return res.status(403).json({error:'Only a Super Admin can create another Super Admin'});}}const hash=await bcrypt.hash(password,12);const u=(await q('INSERT INTO users(name,email,password_hash) VALUES($1,$2,$3) RETURNING id,name,email,status,created_at',[name.trim(),email.toLowerCase().trim(),hash]))[0];if(roleId)await pool.query('INSERT INTO user_roles(user_id,role_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[u.id,roleId]);for(const b of branchIds)await pool.query('INSERT INTO user_branches(user_id,branch_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[u.id,b]);await audit(req.user,'STAFF_CREATED','User',u.id,'Created staff account',null,u,req.req);res.status(201).json(u)});
app.put('/api/users/:id/roles',auth,need('staff.manage'),async(req,res)=>{
  const id=req.params.id;
  const roles=Array.isArray(req.body?.roleIds)?[...new Set(req.body.roleIds.map(String))]:[];
  const target=(await q('SELECT id,name,email,status FROM users WHERE id=$1',[id]))[0];
  if(!target)return res.status(404).json({error:'User not found'});
  if(!roles.length)return res.status(400).json({error:'At least one role is required'});
  const valid=await q('SELECT id,name,system FROM roles WHERE id=ANY($1::uuid[])',[roles]);
  if(valid.length!==roles.length)return res.status(400).json({error:'One or more selected roles do not exist'});
  const actorIsSuper=(await q("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 AND r.name='Super Admin' LIMIT 1",[req.user.id]))[0];
  if(!actorIsSuper && valid.some(r=>r.name==='Super Admin'))return res.status(403).json({error:'Only a Super Admin can grant the Super Admin role'});
  const targetIsSuper=(await q("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 AND r.name='Super Admin' LIMIT 1",[id]))[0];
  if(targetIsSuper && !actorIsSuper)return res.status(403).json({error:'Only a Super Admin can change another Super Admin roles'});
  if(targetIsSuper && !valid.some(r=>r.name==='Super Admin')){
    const count=(await q("SELECT count(*)::int c FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.status='Active' AND r.name='Super Admin'"))[0].c;
    if(count<=1)return res.status(400).json({error:'At least one active Super Admin must remain'});
  }
  await pool.query('BEGIN');
  try{
    const before=await q('SELECT r.id,r.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 ORDER BY r.name',[id]);
    await pool.query('DELETE FROM user_roles WHERE user_id=$1',[id]);
    for(const roleId of roles)await pool.query('INSERT INTO user_roles(user_id,role_id) VALUES($1,$2)',[id,roleId]);
    const after=await q('SELECT r.id,r.name FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 ORDER BY r.name',[id]);
    await pool.query('COMMIT');
    await audit(req.user,'STAFF_ROLES_CHANGED','User',id,'Updated staff roles',before,after,req.req);
    res.json({user:target,roles:after});
  }catch(e){try{await pool.query('ROLLBACK')}catch{};console.error('Role assignment failed',e);res.status(500).json({error:'Unable to update staff roles'});}
});

app.delete('/api/users/:id',auth,superAdminOnly,async(req,res)=>{
  const id=req.params.id;
  if(id===req.user.id)return res.status(400).json({error:'You cannot delete your own account'});
  const target=(await q('SELECT id,name,email,status FROM users WHERE id=$1',[id]))[0];
  if(!target)return res.status(404).json({error:'User not found'});
  const isSuper=(await q("SELECT 1 FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE ur.user_id=$1 AND r.name='Super Admin' LIMIT 1",[id]))[0];
  if(isSuper){
    const count=(await q("SELECT count(*)::int c FROM users u JOIN user_roles ur ON ur.user_id=u.id JOIN roles r ON r.id=ur.role_id WHERE u.status='Active' AND r.name='Super Admin'"))[0].c;
    if(count<=1)return res.status(400).json({error:'You cannot delete the last active Super Admin account'});
  }
  if(String(req.body?.confirmation||'').trim()!==target.email)return res.status(400).json({error:'Type the user email exactly to confirm permanent deletion'});
  const client=await pool.connect();
  try{
    await client.query('BEGIN');
    // Business records keep their actor/user foreign keys. The identity is tombstoned
    // instead of physically deleting the row, which preserves NOT NULL historical links
    // such as sales.cashier_id while permanently preventing authentication.
    const tombstoneEmail=`deleted+${id}@invalid.local`;
    const randomPassword=await bcrypt.hash(crypto.randomBytes(48).toString('base64url'),12);
    await client.query('DELETE FROM user_roles WHERE user_id=$1',[id]);
    await client.query('DELETE FROM user_branches WHERE user_id=$1',[id]);
    await client.query('DELETE FROM sessions WHERE user_id=$1',[id]);
    await client.query('DELETE FROM trusted_devices WHERE user_id=$1',[id]);
    await client.query('DELETE FROM mfa_credentials WHERE user_id=$1',[id]);
    await client.query('DELETE FROM password_history WHERE user_id=$1',[id]);
    await client.query('DELETE FROM notifications WHERE user_id=$1',[id]);
    await client.query('UPDATE email_delivery_logs SET email=$1 WHERE user_id=$2',[tombstoneEmail,id]);
    await client.query('UPDATE password_reset_tokens SET used_at=COALESCE(used_at,now()) WHERE user_id=$1 AND used_at IS NULL',[id]);
    await client.query("UPDATE departments SET manager_id=NULL,updated_at=now() WHERE manager_id=$1",[id]);
    await client.query(`UPDATE users SET name='Deleted User',email=$1,password_hash=$2,status='Suspended',phone='',employee_id=NULL,job_title='',department_id=NULL,country_code='',locale='en',timezone='UTC',failed_attempts=0,locked_until=NULL,mfa_enabled=false,email_verified_at=NULL,updated_at=now(),updated_by=NULL WHERE id=$3`,[tombstoneEmail,randomPassword,id]);
    await client.query('COMMIT');
    await audit(req.user,'STAFF_DELETED','User',id,`Permanently disabled and anonymized staff account ${target.email}`,target,{id,name:'Deleted User',email:tombstoneEmail,status:'Suspended'},req.req);
    res.json({ok:true,deletedUserId:id,mode:'anonymized_tombstone',message:'The staff account was immediately deactivated, removed from active staff and moved to Deleted Staff. Historical business records remain intact.'});
  }catch(e){try{await client.query('ROLLBACK')}catch{};console.error('User deletion failed',e);res.status(409).json({error:'The user could not be deleted safely.',detail:process.env.NODE_ENV==='development'?String(e.message):undefined});}
  finally{client.release();}
});
