app.post('/api/security/mfa/enable',auth,async(req,res)=>{const row=(await q('SELECT secret_encrypted FROM mfa_credentials WHERE user_id=$1',[req.user.id]))[0];if(!row)return res.status(404).json({error:'Start MFA setup first'});if(!verifyTotp(decryptSecret(row.secret_encrypted),req.body?.code))return res.status(400).json({error:'Invalid authenticator code'});await pool.query('UPDATE mfa_credentials SET enabled_at=now(),updated_at=now() WHERE user_id=$1',[req.user.id]);await pool.query('UPDATE users SET mfa_enabled=true,updated_at=now() WHERE id=$1',[req.user.id]);await audit(req.user,'MFA_ENABLED','Security',req.user.id,'Enabled multi-factor authentication',null,{enabled:true},req.req);res.json({enabled:true})});
app.post('/api/security/mfa/disable',auth,async(req,res)=>{const u=(await q('SELECT mfa_enabled FROM users WHERE id=$1',[req.user.id]))[0];if(!u?.mfa_enabled)return res.json({enabled:false});const row=(await q('SELECT secret_encrypted FROM mfa_credentials WHERE user_id=$1',[req.user.id]))[0];if(!row||!verifyTotp(decryptSecret(row.secret_encrypted),req.body?.code))return res.status(400).json({error:'Valid MFA code required'});await pool.query('DELETE FROM mfa_credentials WHERE user_id=$1',[req.user.id]);await pool.query('UPDATE users SET mfa_enabled=false,updated_at=now() WHERE id=$1',[req.user.id]);await pool.query('UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND id<>$2 AND revoked_at IS NULL',[req.user.id,req.session.id]);await audit(req.user,'MFA_DISABLED','Security',req.user.id,'Disabled multi-factor authentication',{enabled:true},{enabled:false},req.req);res.json({enabled:false})});
