app.post('/api/security/password/change',auth,async(req,res)=>{const {currentPassword,newPassword}=req.body||{};const u=(await q('SELECT * FROM users WHERE id=$1',[req.user.id]))[0];const policy=Object.fromEntries((await q("SELECT key,value_json FROM settings WHERE key LIKE 'password%'")).map(x=>[x.key,safeJson(x.value_json)]));const pErr=passwordError(newPassword,policy);if(!currentPassword||pErr)return res.status(400).json({error:pErr||'Current password is required'});if(!(await bcrypt.compare(currentPassword,u.password_hash)))return res.status(400).json({error:'Current password is incorrect'});const history=await q('SELECT password_hash FROM password_history WHERE user_id=$1 ORDER BY created_at DESC LIMIT 5',[u.id]);if([u.password_hash,...history.map(x=>x.password_hash)].some(h=>bcrypt.compareSync(newPassword,h)))return res.status(400).json({error:'Do not reuse a recent password'});const hash=await bcrypt.hash(newPassword,12);await pool.query('UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2',[hash,u.id]);await pool.query('INSERT INTO password_history(user_id,password_hash) VALUES($1,$2)',[u.id,u.password_hash]);await pool.query('UPDATE sessions SET revoked_at=now() WHERE user_id=$1 AND id<>$2 AND revoked_at IS NULL',[u.id,req.session.id]);await audit(req.user,'PASSWORD_CHANGED','Security',u.id,'Changed administrator password',null,null,req.req);res.json({ok:true})});
