app.patch('/api/users/:id/profile',auth,need('staff.profile.manage'),async(req,res)=>{const old=(await q('SELECT id,name,email,phone,employee_id,job_title,department_id,country_code,locale,timezone,status FROM users WHERE id=$1',[req.params.id]))[0];if(!old)return res.status(404).json({error:'User not found'});const b=req.body||{};if(b.departmentId&&!(await q('SELECT id FROM departments WHERE id=$1',[b.departmentId]))[0])return res.status(400).json({error:'Department not found'});const hasDepartment=Object.prototype.hasOwnProperty.call(b,'departmentId');const u=(await q('UPDATE users SET name=COALESCE($1,name),phone=COALESCE($2,phone),employee_id=COALESCE($3,employee_id),job_title=COALESCE($4,job_title),department_id=CASE WHEN $5 THEN $6::uuid ELSE department_id END,country_code=COALESCE($7,country_code),locale=COALESCE($8,locale),timezone=COALESCE($9,timezone),updated_by=$10,updated_at=now() WHERE id=$11 RETURNING id,name,email,phone,employee_id,job_title,department_id,country_code,locale,timezone,status,updated_at',[b.name,b.phone,b.employeeId,b.jobTitle,hasDepartment,b.departmentId||null,b.countryCode,b.locale,b.timezone,req.user.id,req.params.id]))[0];await audit(req.user,'STAFF_PROFILE_UPDATED','User',u.id,'Updated staff profile',old,u,req.req);res.json(u)});
app.get('/api/audit/search',auth,need('audit.view'),async(req,res)=>{const limit=Math.min(Number(req.query.limit)||100,500);const offset=Math.max(Number(req.query.offset)||0,0);const params=[];const where=[];if(req.query.action){params.push(req.query.action);where.push(`a.action=$${params.length}`)}if(req.query.resourceType){params.push(req.query.resourceType);where.push(`a.resource_type=$${params.length}`)}if(req.query.actor){params.push(req.query.actor);where.push(`a.actor_id=$${params.length}`)}if(req.query.from){params.push(req.query.from);where.push(`a.created_at >= $${params.length}`)}if(req.query.to){params.push(req.query.to);where.push(`a.created_at <= $${params.length}`)}params.push(limit);params.push(offset);const sql=`SELECT a.*,u.email actor_email,b.name branch_name FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id LEFT JOIN branches b ON b.id=a.branch_id ${where.length?'WHERE '+where.join(' AND '):''} ORDER BY a.created_at DESC LIMIT $${params.length-1} OFFSET $${params.length}`;res.json(await q(sql,params))});
app.get('/api/audit/export',auth,need('audit.export'),async(req,res)=>{const limit=Math.min(Number(req.query.limit)||5000,10000);const rows=await q('SELECT a.created_at,a.action,a.resource_type,a.resource_id,a.detail,u.email actor_email,a.ip,a.user_agent,a.request_id FROM audit_logs a LEFT JOIN users u ON u.id=a.actor_id ORDER BY a.created_at DESC LIMIT $1',[limit]);const esc=v=>{const x=String(v??'');return /[\",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x};const csv=['created_at,action,resource_type,resource_id,detail,actor_email,ip,user_agent,request_id',...rows.map(r=>[r.created_at,r.action,r.resource_type,r.resource_id,r.detail,r.actor_email,r.ip,r.user_agent,r.request_id].map(esc).join(','))].join('\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename=amaal-audit-export.csv');res.send(csv)});
