app.post('/api/catalog/products/:id/images',auth,need('catalog.manage'),async(req,res)=>{const b=req.body||{};const mediaId=String(b.mediaId||'');if(!mediaId)return res.status(410).json({error:'Direct image URLs are no longer accepted. Upload or select a managed public media asset and attach it with mediaId.'});const m=(await q("SELECT id FROM media_assets WHERE id=$1 AND status='Active' AND visibility='Public'",[mediaId]))[0];if(!m)return res.status(404).json({error:'Active public media asset not found.'});const p=(await q('SELECT id FROM products WHERE id=$1',[req.params.id]))[0];if(!p)return res.status(404).json({error:'Product not found.'});let variantId=b.variantId||null;if(variantId){const v=(await q('SELECT id FROM product_variants WHERE id=$1 AND product_id=$2',[variantId,p.id]))[0];if(!v)return res.status(400).json({error:'Selected variant does not belong to this product.'});}const i=(await q('INSERT INTO product_images(product_id,variant_id,media_id,url,alt_text,sort_order,is_primary) VALUES($1,$2,$3,$4,$5,$6,$7) RETURNING *',[p.id,variantId,mediaId,`/api/public/media/${mediaId}/file`,String(b.altText||''),Math.max(0,Number(b.sortOrder||0)),Boolean(b.isPrimary)]))[0];if(i.is_primary)await pool.query('UPDATE product_images SET is_primary=false WHERE product_id=$1 AND id<>$2',[p.id,i.id]);await audit(req.user,'PRODUCT_IMAGE_ADDED','ProductImage',i.id,'Added managed product image',null,i,req.req);res.status(201).json(i)});
app.patch('/api/catalog/products/:id/publish',auth,need('catalog.publish'),async(req,res)=>{const old=(await q('SELECT p.id,p.name,p.status,p.website_visibility,p.description,p.brand_id,p.category_id,EXISTS(SELECT 1 FROM product_images pi JOIN media_assets m ON m.id=pi.media_id WHERE pi.product_id=p.id AND m.status=\'Active\' AND m.visibility=\'Public\') has_image,EXISTS(SELECT 1 FROM product_variants v WHERE v.product_id=p.id AND v.status=\'Active\' AND v.selling_price>0) has_price FROM products p WHERE p.id=$1',[req.params.id]))[0];if(!old)return res.status(404).json({error:'Product not found'});if(req.body?.published===true){if(old.status!=='Active')return res.status(400).json({error:'Only Active products can be published'});const gaps=[];if(!old.brand_id)gaps.push('brand');if(!old.category_id)gaps.push('category');if(!String(old.description||'').trim())gaps.push('description');if(!old.has_image)gaps.push('image');if(!old.has_price)gaps.push('active priced variant');const seo=catalogSeoIssues(old);for(const issue of seo)gaps.push(issue);if(gaps.length)return res.status(400).json({error:'Product is not ready for public publication',missing:gaps})}const p=(await q("UPDATE products SET website_visibility=$1,updated_by=$2,updated_at=now() WHERE id=$3 RETURNING id,name,status,website_visibility",[req.body?.published?'Published':'Hidden',req.user.id,req.params.id]))[0];await audit(req.user,p.website_visibility==='Published'?'PRODUCT_PUBLISHED':'PRODUCT_UNPUBLISHED','Product',p.id,'Changed website publication status',old,p,req.req);res.json(p)});
