// Catalogue management: safe archive/delete controls and public collections.
app.delete('/api/catalog/categories/:id',auth,need('catalog.manage'),async(req,res)=>{
  const old=(await q('SELECT * FROM product_categories WHERE id=$1',[req.params.id]))[0];
  if(!old)return res.status(404).json({error:'Category not found'});
  const linked=(await q('SELECT count(*)::int c FROM products WHERE category_id=$1',[req.params.id]))[0].c;
  const children=(await q('SELECT count(*)::int c FROM product_categories WHERE parent_id=$1',[req.params.id]))[0].c;
  if(linked||children)return res.status(409).json({error:`This category is still in use by ${linked} product(s)${children?` and ${children} subcategory(s)`:''}. Archive it instead.`});
  await q('DELETE FROM product_categories WHERE id=$1',[req.params.id]);
  await audit(req.user,'CATALOG_CATEGORY_DELETED','ProductCategory',req.params.id,`Deleted category ${old.name}`,old,null,req.req);
  res.json({ok:true});
});
