app.post('/api/inventory/locations',auth,need('inventory.manage'),async(req,res)=>{const b=req.body||{};if(!String(b.name||'').trim()||!String(b.code||'').trim())return res.status(400).json({error:'Location name and code are required'});const l=(await q('INSERT INTO inventory_locations(name,code,type,address,notes,status) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[String(b.name).trim(),String(b.code).trim().toUpperCase(),b.type||'Warehouse',String(b.address||''),String(b.notes||''),b.status||'Active'])).at(0);await audit(req.user,'INVENTORY_LOCATION_CREATED','InventoryLocation',l.id,`Created inventory location ${l.name}`,null,l,req.req);res.status(201).json(l)});
app.patch('/api/inventory/locations/:id',auth,need('inventory.manage'),async(req,res)=>{const old=(await q('SELECT * FROM inventory_locations WHERE id=$1',[req.params.id]))[0];if(!old)return res.status(404).json({error:'Location not found'});const b=req.body||{};if(b.status==='Inactive'&&old.status!=='Inactive'){const active=(await q('SELECT COALESCE(SUM(on_hand),0)::numeric on_hand,COALESCE(SUM(reserved),0)::numeric reserved FROM inventory_balances WHERE location_id=$1',[req.params.id]))[0];const serialized=(await q("SELECT count(*)::int c FROM serialized_units WHERE location_id=$1 AND status IN ('In Stock','Reserved','Transferred','Service')",[req.params.id]))[0].c;if(Number(active.on_hand)>0||Number(active.reserved)>0||serialized>0)return res.status(409).json({error:'Location cannot be deactivated while inventory or active serialized units remain. Move or reconcile stock first.'})}const l=(await q('UPDATE inventory_locations SET name=COALESCE($1,name),code=COALESCE($2,code),type=COALESCE($3,type),address=COALESCE($4,address),notes=COALESCE($5,notes),status=COALESCE($6,status),updated_at=now() WHERE id=$7 RETURNING *',[b.name,b.code?String(b.code).toUpperCase():undefined,b.type,b.address,b.notes,b.status,req.params.id]))[0];await audit(req.user,'INVENTORY_LOCATION_UPDATED','InventoryLocation',l.id,'Updated inventory location',old,l,req.req);res.json(l)});
app.get('/api/inventory/stock',auth,need('inventory.view'),async(req,res)=>{const limit=Math.min(Math.max(Number(req.query.limit)||50,1),200);const offset=Math.max(Number(req.query.offset)||0,0);const params=[];const w=[];if(req.query.q){params.push(`%${String(req.query.q).trim()}%`);w.push(`(v.sku ILIKE $${params.length} OR v.variant_name ILIKE $${params.length} OR p.name ILIKE $${params.length} OR COALESCE(b.name,'') ILIKE $${params.length})`)}if(req.query.locationId){params.push(req.query.locationId);w.push(`ib.location_id=$${params.length}`)}if(req.query.low==='true')w.push('ib.on_hand-ib.reserved<=5 AND ib.on_hand>0');const where=w.length?'WHERE '+w.join(' AND '):'';const count=(await q(`SELECT count(*)::int c FROM inventory_balances ib JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN brands b ON b.id=p.brand_id ${where}`,params))[0].c;params.push(limit,offset);const rows=await q(`SELECT ib.id,ib.variant_id,ib.location_id,ib.on_hand,ib.reserved,(ib.on_hand-ib.reserved) available,ib.updated_at,v.sku,v.variant_name,v.serialized,v.cost_price,v.selling_price,p.name product_name,b.name brand_name,l.name location_name,CASE WHEN v.serialized THEN (SELECT count(*)::int FROM serialized_units su WHERE su.variant_id=v.id) ELSE NULL END serialized_units,CASE WHEN v.serialized THEN (SELECT count(*)::int FROM serialized_units su WHERE su.variant_id=v.id AND su.status='In Stock' AND su.location_id=ib.location_id) ELSE NULL END serialized_available FROM inventory_balances ib JOIN product_variants v ON v.id=ib.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN brands b ON b.id=p.brand_id JOIN inventory_locations l ON l.id=ib.location_id ${where} ORDER BY ib.updated_at DESC LIMIT $${params.length-1} OFFSET $${params.length}`,params);res.json({rows,total:count,limit,offset})});
app.get('/api/inventory/movements',auth,need('inventory.view'),async(req,res)=>{const limit=Math.min(Number(req.query.limit)||100,500);res.json(await q(`SELECT m.*,v.sku,v.variant_name,p.name product_name,l.name location_name,u.email actor_email FROM inventory_movements m JOIN product_variants v ON v.id=m.variant_id JOIN products p ON p.id=v.product_id JOIN inventory_locations l ON l.id=m.location_id LEFT JOIN users u ON u.id=m.actor_id ORDER BY m.created_at DESC LIMIT $1`,[limit]))});
app.post('/api/inventory/receipts',auth,need('inventory.receive'),async(req,res)=>{const b=req.body||{};if(!b.locationId||!Array.isArray(b.lines)||!b.lines.length)return res.status(400).json({error:'Location and at least one receipt line are required'});const client=await pool.connect();try{await client.query('BEGIN');const receipt=(await client.query('INSERT INTO stock_receipts(receipt_no,location_id,supplier_name,supplier_reference,notes,created_by) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[inventoryNo('GRN'),b.locationId,String(b.supplierName||''),String(b.supplierReference||''),String(b.notes||''),req.user.id])).rows[0];for(const line of b.lines){const qty=Number(line.quantity);if(!(qty>0))throw new Error('Receipt quantity must be greater than zero');const variant=(await client.query('SELECT * FROM product_variants WHERE id=$1',[line.variantId])).rows[0];if(!variant)throw new Error('Variant not found');const serials=Array.isArray(line.serials)?line.serials:[];if(variant.serialized && serials.length!==qty)throw new Error(`Serialized SKU ${variant.sku} requires exactly ${qty} serial/IMEI records`);if(variant.serialized){const seen=new Set();for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const ids=[x.serialNumber,x.imei1,x.imei2,x.barcode,x.qrCode].map(v=>String(v||'').trim()).filter(Boolean);if(!ids.length)throw new Error(`Every serialized unit for ${variant.sku} needs an identifier`);for(const id of ids){const k=id.toLowerCase();if(seen.has(k))throw new Error(`Duplicate identifier ${id} in this receipt`);seen.add(k);}const conflict=(await client.query('SELECT id FROM serialized_units WHERE serial_number=ANY($1) OR imei1=ANY($1) OR imei2=ANY($1) OR barcode=ANY($1) OR qr_code=ANY($1) LIMIT 1',[ids])).rows[0];if(conflict)throw new Error(`A serialized unit with identifier ${ids[0]} already exists`);}}const batchNumber=String(line.batchNumber||'').trim()||`${receipt.receipt_no}-${variant.sku}`;let batch=(await client.query('SELECT * FROM inventory_batches WHERE batch_number=$1 FOR UPDATE',[batchNumber])).rows[0];if(batch)throw new Error(`Batch ${batchNumber} already exists. Use a unique batch number.`);batch=(await client.query('INSERT INTO inventory_batches(batch_number,variant_id,location_id,supplier_name,supplier_reference,quantity_received,notes,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[batchNumber,variant.id,b.locationId,String(b.supplierName||''),String(b.supplierReference||''),qty,String(b.notes||''),req.user.id])).rows[0];const rl=(await client.query('INSERT INTO stock_receipt_lines(receipt_id,variant_id,quantity,unit_cost,serials,batch_id) VALUES($1,$2,$3,$4,$5,$6) RETURNING *',[receipt.id,variant.id,qty,Number(line.unitCost??variant.cost_price),JSON.stringify(serials),batch.id])).rows[0];await changeStock(client,{variantId:variant.id,locationId:b.locationId,delta:qty,type:'RECEIPT',actorId:req.user.id,referenceType:'StockReceipt',referenceId:receipt.id,reason:`Goods receipt ${receipt.receipt_no}`,unitCost:Number(line.unitCost??variant.cost_price)});await client.query("SELECT set_config('app.actor_id',$1,true)",[req.user.id]);for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;await client.query('INSERT INTO serialized_units(variant_id,location_id,batch_id,serial_number,imei1,imei2,status,unit_cost,supplier_name,supplier_reference,received_by,received_at) VALUES($1,$2,$3,$4,$5,$6,\'In Stock\',$7,$8,$9,$10,now())',[variant.id,b.locationId,batch.id,x.serialNumber||null,x.imei1||null,x.imei2||null,Number(line.unitCost??variant.cost_price),String(b.supplierName||''),String(b.supplierReference||''),req.user.id])}}
await client.query('COMMIT');await audit(req.user,'STOCK_RECEIVED','StockReceipt',receipt.id,`Received stock ${receipt.receipt_no}`,null,receipt,req.req);res.status(201).json(receipt)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/receipts',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT r.*,l.name location_name,COUNT(rl.id)::int line_count,COALESCE(SUM(rl.quantity),0)::numeric units FROM stock_receipts r JOIN inventory_locations l ON l.id=r.location_id LEFT JOIN stock_receipt_lines rl ON rl.receipt_id=r.id GROUP BY r.id,l.name ORDER BY r.created_at DESC LIMIT 200`)));
app.post('/api/inventory/adjustments',auth,need('inventory.adjust'),async(req,res)=>{const b=req.body||{};if(!b.locationId||!String(b.reason||'').trim()||!Array.isArray(b.lines)||!b.lines.length)return res.status(400).json({error:'Location, reason and adjustment lines are required'});const client=await pool.connect();try{await client.query('BEGIN');const a=(await client.query('INSERT INTO stock_adjustments(adjustment_no,location_id,reason,created_by) VALUES($1,$2,$3,$4) RETURNING *',[inventoryNo('ADJ'),b.locationId,String(b.reason).trim(),req.user.id])).rows[0];for(const line of b.lines){const delta=Number(line.quantityChange);if(!delta)throw new Error('Adjustment quantity cannot be zero');const variant=(await client.query('SELECT * FROM product_variants WHERE id=$1',[line.variantId])).rows[0];if(!variant)throw new Error('Variant not found');const serials=Array.isArray(line.serials)?line.serials:[];if(variant.serialized&&(!Number.isInteger(Math.abs(delta))||serials.length!==Math.abs(delta)))throw new Error(`Serialized SKU ${variant.sku} requires one serial/IMEI record per adjusted unit`);await client.query('INSERT INTO stock_adjustment_lines(adjustment_id,variant_id,quantity_change,unit_cost,reason) VALUES($1,$2,$3,$4,$5)',[a.id,variant.id,delta,line.unitCost==null?variant.cost_price:Number(line.unitCost),String(line.reason||b.reason)]);await changeStock(client,{variantId:variant.id,locationId:b.locationId,delta,type:delta>0?'ADJUSTMENT_IN':'ADJUSTMENT_OUT',actorId:req.user.id,referenceType:'StockAdjustment',referenceId:a.id,reason:String(line.reason||b.reason),unitCost:Number(line.unitCost??variant.cost_price)});if(variant.serialized){for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const identifiers=[x.serialNumber,x.imei1,x.imei2,x.barcode,x.qrCode].map(v=>String(v||'').trim()).filter(Boolean);if(new Set(identifiers.map(v=>v.toLowerCase())).size!==identifiers.length)throw new Error('A physical unit cannot reuse the same identifier in one adjustment');const conflict=(await client.query('SELECT id FROM serialized_units WHERE serial_number=ANY($1) OR imei1=ANY($1) OR imei2=ANY($1) OR barcode=ANY($1) OR qr_code=ANY($1) LIMIT 1 FOR UPDATE',[identifiers])).rows[0];const su=conflict? (await client.query('SELECT * FROM serialized_units WHERE id=$1 FOR UPDATE',[conflict.id])).rows[0]:null;if(delta<0){if(!su||su.location_id!==b.locationId||su.status!=='In Stock')throw new Error('Serialized unit is not available at this location');await transitionSerializedUnit(client,{unitId:su.id,toStatus:'Damaged',actorId:req.user.id,reason:String(line.reason||b.reason),sourceType:'StockAdjustment',sourceId:a.id,clearLocation:true})}else{if(su)throw new Error('A physical unit with one of those identifiers already exists');await client.query("SELECT set_config('app.actor_id',$1,true)",[req.user.id]);await client.query("INSERT INTO serialized_units(variant_id,location_id,serial_number,imei1,imei2,barcode,qr_code,status,unit_cost,received_at) VALUES($1,$2,$3,$4,$5,$6,$7,'In Stock',$8,now())",[variant.id,b.locationId,x.serialNumber||null,x.imei1||null,x.imei2||null,x.barcode||null,x.qrCode||null,Number(line.unitCost??variant.cost_price)])}}}}await client.query('COMMIT');await audit(req.user,'STOCK_ADJUSTED','StockAdjustment',a.id,`Applied stock adjustment ${a.adjustment_no}`,null,a,req.req);res.status(201).json(a)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/adjustments',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT a.*,l.name location_name,COUNT(al.id)::int line_count,COALESCE(SUM(al.quantity_change),0)::numeric net_change FROM stock_adjustments a JOIN inventory_locations l ON l.id=a.location_id LEFT JOIN stock_adjustment_lines al ON al.adjustment_id=a.id GROUP BY a.id,l.name ORDER BY a.created_at DESC LIMIT 200`)));
app.post('/api/inventory/transfers',auth,need('inventory.transfer'),async(req,res)=>{const b=req.body||{};if(!b.fromLocationId||!b.toLocationId||b.fromLocationId===b.toLocationId||!Array.isArray(b.lines)||!b.lines.length)return res.status(400).json({error:'Two different locations and at least one transfer line are required'});const client=await pool.connect();try{await client.query('BEGIN');const t=(await client.query('INSERT INTO stock_transfers(transfer_no,from_location_id,to_location_id,notes,requested_by,status) VALUES($1,$2,$3,$4,$5,\'Submitted\') RETURNING *',[inventoryNo('TRF'),b.fromLocationId,b.toLocationId,String(b.notes||''),req.user.id])).rows[0];const transferSeen=new Set();for(const line of b.lines){const qty=Number(line.quantity);if(!(qty>0))throw new Error('Transfer quantity must be greater than zero');const v=(await client.query('SELECT * FROM product_variants WHERE id=$1',[line.variantId])).rows[0];if(!v)throw new Error('Variant not found');const serials=Array.isArray(line.serials)?line.serials:[];if(v.serialized&&(!Number.isInteger(qty)||serials.length!==qty))throw new Error(`Serialized SKU ${v.sku} requires exactly ${qty} physical units`);if(v.serialized){for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const ids=[x.serialNumber,x.imei1,x.imei2,x.barcode,x.qrCode].filter(Boolean).map((z)=>String(z).trim().toLowerCase());const key=ids[0]||'';if(!key||ids.some((z)=>transferSeen.has(z)))throw new Error(`Duplicate or missing identifier for ${v.sku}`);ids.forEach((z)=>transferSeen.add(z));const su=(await client.query('SELECT id,status,location_id FROM serialized_units WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$3 OR imei2=$4 OR barcode=$5 OR qr_code=$6) FOR UPDATE',[v.id,x.serialNumber||'',x.imei1||'',x.imei2||'',x.barcode||'',x.qrCode||''])).rows[0];if(!su||su.location_id!==b.fromLocationId||su.status!=='In Stock')throw new Error(`Serialized unit ${key} is not available at the source location`);}}await client.query('INSERT INTO stock_transfer_lines(transfer_id,variant_id,quantity,unit_cost,serials) VALUES($1,$2,$3,$4,$5)',[t.id,v.id,qty,Number(line.unitCost??v.cost_price),JSON.stringify(serials)])}await client.query('COMMIT');await audit(req.user,'STOCK_TRANSFER_CREATED','StockTransfer',t.id,`Created transfer ${t.transfer_no}`,null,t,req.req);res.status(201).json(t)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/transfers',auth,need('inventory.view'),async(req,res)=>res.json(await q(`SELECT t.*,fl.name from_location_name,tl.name to_location_name,COUNT(l.id)::int line_count,COALESCE(SUM(l.quantity),0)::numeric units FROM stock_transfers t JOIN inventory_locations fl ON fl.id=t.from_location_id JOIN inventory_locations tl ON tl.id=t.to_location_id LEFT JOIN stock_transfer_lines l ON l.transfer_id=t.id GROUP BY t.id,fl.name,tl.name ORDER BY t.created_at DESC LIMIT 200`)));
app.patch('/api/inventory/transfers/:id/approve',auth,need('inventory.transfer'),async(req,res)=>{const t=(await q("SELECT * FROM stock_transfers WHERE id=$1 AND status='Submitted'",[req.params.id]))[0];if(!t)return res.status(404).json({error:'Submitted transfer not found'});const r=(await q("UPDATE stock_transfers SET status='Approved',approved_by=$1,updated_at=now() WHERE id=$2 RETURNING *",[req.user.id,t.id]))[0];await audit(req.user,'STOCK_TRANSFER_APPROVED','StockTransfer',r.id,'Approved stock transfer',t,r,req.req);res.json(r)});
app.get('/api/inventory/transfers/:id',auth,need('inventory.view'),async(req,res)=>{const t=(await q(`SELECT t.*,fl.name from_location_name,tl.name to_location_name,u.email requested_by_email,au.email approved_by_email FROM stock_transfers t JOIN inventory_locations fl ON fl.id=t.from_location_id JOIN inventory_locations tl ON tl.id=t.to_location_id LEFT JOIN users u ON u.id=t.requested_by LEFT JOIN users au ON au.id=t.approved_by WHERE t.id=$1`,[req.params.id]))[0];if(!t)return res.status(404).json({error:'Transfer not found'});t.lines=await q(`SELECT l.*,v.sku,v.variant_name,p.name product_name,v.serialized FROM stock_transfer_lines l JOIN product_variants v ON v.id=l.variant_id JOIN products p ON p.id=v.product_id WHERE l.transfer_id=$1 ORDER BY p.name,v.sku`,[t.id]);res.json(t)});
app.patch('/api/inventory/transfers/:id/ship',auth,need('inventory.transfer'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const t=(await client.query("SELECT * FROM stock_transfers WHERE id=$1 AND status='Approved' FOR UPDATE",[req.params.id])).rows[0];if(!t)throw new Error('Transfer is not ready to ship');const lines=(await client.query('SELECT l.*,v.serialized FROM stock_transfer_lines l JOIN product_variants v ON v.id=l.variant_id WHERE l.transfer_id=$1',[t.id])).rows;for(const line of lines){const serials=Array.isArray(line.serials)?line.serials:[];if(line.serialized&&serials.length!==Number(line.quantity))throw new Error(`Serialized transfer line requires exactly ${line.quantity} physical units`);if(line.serialized){for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const key=String(x.serialNumber||x.imei1||x.imei2||x.barcode||x.qrCode||'').trim();const su=(await client.query("SELECT id,status,location_id FROM serialized_units WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$3 OR imei2=$4 OR barcode=$5 OR qr_code=$6) FOR UPDATE",[line.variant_id,x.serialNumber||'',x.imei1||'',x.imei2||'',x.barcode||'',x.qrCode||''])).rows[0];if(!su||su.location_id!==t.from_location_id||su.status!=='In Stock')throw new Error(`Serialized unit ${key||'unknown'} is no longer available at the source location`)}}await changeStock(client,{variantId:line.variant_id,locationId:t.from_location_id,delta:-Number(line.quantity),type:'TRANSFER_OUT',actorId:req.user.id,referenceType:'StockTransfer',referenceId:t.id,reason:`Transfer ${t.transfer_no}`});if(line.serialized){for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const su=(await client.query("SELECT id FROM serialized_units WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$3 OR imei2=$4 OR barcode=$5 OR qr_code=$6) FOR UPDATE",[line.variant_id,x.serialNumber||'',x.imei1||'',x.imei2||'',x.barcode||'',x.qrCode||''])).rows[0];if(!su)throw new Error('Serialized unit not found for transfer');await transitionSerializedUnit(client,{unitId:su.id,toStatus:'Transferred',actorId:req.user.id,reason:`Transfer ${t.transfer_no} shipped`,sourceType:'StockTransfer',sourceId:t.id,clearLocation:true})}}}const r=(await client.query("UPDATE stock_transfers SET status='Shipped',shipped_at=now(),updated_at=now() WHERE id=$1 RETURNING *",[t.id])).rows[0];await client.query('COMMIT');await audit(req.user,'STOCK_TRANSFER_SHIPPED','StockTransfer',r.id,'Shipped stock transfer',t,r,req.req);res.json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.patch('/api/inventory/transfers/:id/receive',auth,need('inventory.transfer'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const t=(await client.query("SELECT * FROM stock_transfers WHERE id=$1 AND status='Shipped' FOR UPDATE",[req.params.id])).rows[0];if(!t)throw new Error('Shipped transfer not found');const lines=(await client.query('SELECT l.*,v.serialized FROM stock_transfer_lines l JOIN product_variants v ON v.id=l.variant_id WHERE l.transfer_id=$1',[t.id])).rows;for(const line of lines){const serials=Array.isArray(line.serials)?line.serials:[];if(line.serialized&&serials.length!==Number(line.quantity))throw new Error(`Serialized transfer line requires exactly ${line.quantity} physical units`);await changeStock(client,{variantId:line.variant_id,locationId:t.to_location_id,delta:Number(line.quantity),type:'TRANSFER_IN',actorId:req.user.id,referenceType:'StockTransfer',referenceId:t.id,reason:`Transfer ${t.transfer_no}`,unitCost:line.unit_cost});if(line.serialized){for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const key=String(x.serialNumber||x.imei1||x.imei2||x.barcode||x.qrCode||'').trim();const su=(await client.query("SELECT id,status,location_id FROM serialized_units WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$3 OR imei2=$4 OR barcode=$5 OR qr_code=$6) FOR UPDATE",[line.variant_id,x.serialNumber||'',x.imei1||'',x.imei2||'',x.barcode||'',x.qrCode||''])).rows[0];if(!su)throw new Error(`Serialized unit ${key||'unknown'} is missing from inventory and cannot be received`);if(su.status!=='Transferred'||su.location_id!==null)throw new Error(`Serialized unit ${key} is not currently in transit`);await transitionSerializedUnit(client,{unitId:su.id,toStatus:'In Stock',locationId:t.to_location_id,actorId:req.user.id,reason:`Transfer ${t.transfer_no} received`,sourceType:'StockTransfer',sourceId:t.id});}}}const r=(await client.query("UPDATE stock_transfers SET status='Received',received_at=now(),updated_at=now() WHERE id=$1 RETURNING *",[t.id])).rows[0];await client.query('COMMIT');await audit(req.user,'STOCK_TRANSFER_RECEIVED','StockTransfer',r.id,'Received stock transfer',t,r,req.req);res.json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/inventory/reservations',auth,need('inventory.reserve'),async(req,res)=>{const b=req.body||{};if(!b.variantId||!b.locationId||!(Number(b.quantity)>0))return res.status(400).json({error:'Variant, location and positive quantity are required'});const client=await pool.connect();try{await client.query('BEGIN');const r=await reserveStock(client,{variantId:b.variantId,locationId:b.locationId,quantity:Number(b.quantity),actorId:req.user.id,referenceType:b.referenceType||null,referenceId:b.referenceId||null,expiresAt:b.expiresAt||null});await client.query('COMMIT');await audit(req.user,'STOCK_RESERVED','InventoryReservation',r.id,'Reserved stock',null,r,req.req);res.status(201).json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
