app.get('/api/catalog/export',auth,need('catalog.export'),async(req,res)=>{const rows=await q(`SELECT p.name product,p.slug,p.product_type,p.status,p.website_visibility,p.featured,b.name brand_name,c.name category_name,v.sku,v.variant_name,v.color,v.storage,v.size,v.cost_price,v.selling_price,v.wholesale_price,v.tax_rate,v.serialized FROM products p LEFT JOIN brands b ON b.id=p.brand_id LEFT JOIN product_categories c ON c.id=p.category_id LEFT JOIN product_variants v ON v.product_id=p.id ORDER BY p.name,v.sku`);const csvEsc=v=>{const x=String(v??'');return /[",\n]/.test(x)?'"'+x.replace(/"/g,'""')+'"':x};const csv=['product,slug,type,status,website_visibility,featured,brand,category,sku,variant,color,storage,size,cost_price,selling_price,wholesale_price,tax_rate,serialized',...rows.map(r=>[r.product,r.slug,r.product_type,r.status,r.website_visibility,r.featured,r.brand_name,r.category_name,r.sku,r.variant_name,r.color,r.storage,r.size,r.cost_price,r.selling_price,r.wholesale_price,r.tax_rate,r.serialized].map(csvEsc).join(','))].join('\n');res.setHeader('Content-Type','text/csv; charset=utf-8');res.setHeader('Content-Disposition','attachment; filename=amaal-catalog-export.csv');res.send(csv)});
