app.get('/api/inventory/overview',auth,need('inventory.view'),async(req,res)=>{
  const [summary,locations,low,dead,serialIssues]=await Promise.all([
    q(`SELECT COALESCE(SUM(on_hand),0)::numeric on_hand,COALESCE(SUM(reserved),0)::numeric reserved,COALESCE(SUM(on_hand-reserved),0)::numeric available,COALESCE(SUM((on_hand-reserved)*COALESCE(v.cost_price,0)),0)::numeric available_cost_value,COUNT(DISTINCT b.variant_id)::int stocked_skus,COUNT(DISTINCT b.location_id)::int locations FROM inventory_balances b JOIN product_variants v ON v.id=b.variant_id WHERE on_hand>0`),
    q(`SELECT l.id,l.name,l.code,l.type,COALESCE(SUM(b.on_hand),0)::numeric on_hand,COALESCE(SUM(b.reserved),0)::numeric reserved,COUNT(DISTINCT b.variant_id)::int skus FROM inventory_locations l LEFT JOIN inventory_balances b ON b.location_id=l.id WHERE l.status='Active' GROUP BY l.id ORDER BY l.name`),
    q(`SELECT v.id,v.sku,v.variant_name,p.name product_name,l.name location_name,(b.on_hand-b.reserved)::numeric available,COALESCE(r.reorder_point,5)::numeric reorder_point,COALESCE(r.reorder_quantity,0)::numeric reorder_quantity FROM inventory_balances b JOIN product_variants v ON v.id=b.variant_id JOIN products p ON p.id=v.product_id JOIN inventory_locations l ON l.id=b.location_id LEFT JOIN inventory_reorder_rules r ON r.variant_id=b.variant_id AND r.location_id=b.location_id WHERE v.status='Active' AND b.on_hand>0 AND b.on_hand-b.reserved<=COALESCE(r.reorder_point,5) ORDER BY (b.on_hand-b.reserved) ASC,p.name LIMIT 100`),
    q(`SELECT v.id,v.sku,v.variant_name,p.name product_name,COALESCE(SUM(b.on_hand),0)::numeric units,MAX(m.last_received) last_received,CASE WHEN MAX(m.last_received) IS NULL THEN NULL ELSE EXTRACT(DAY FROM now()-MAX(m.last_received))::int END age_days FROM product_variants v JOIN products p ON p.id=v.product_id LEFT JOIN inventory_balances b ON b.variant_id=v.id LEFT JOIN (SELECT variant_id,MAX(created_at) last_received FROM inventory_movements WHERE movement_type='RECEIPT' GROUP BY variant_id) m ON m.variant_id=v.id WHERE v.status='Active' GROUP BY v.id,v.sku,v.variant_name,p.name HAVING COALESCE(SUM(b.on_hand),0)>0 ORDER BY age_days DESC NULLS LAST LIMIT 50`),
    q(`SELECT status,COUNT(*)::int count FROM serialized_units GROUP BY status ORDER BY status`)
  ]);
  res.json({summary:summary[0]||{},locations,lowStock:low,ageing:dead,serializedStatus:serialIssues});
});

