app.get('/api/inventory/serialized/:id/history',auth,need('inventory.serialized'),async(req,res)=>{
  const s=(await q(`SELECT s.*,v.sku,v.variant_name,p.name product_name,l.name location_name,b.batch_number FROM serialized_units s JOIN product_variants v ON v.id=s.variant_id JOIN products p ON p.id=v.product_id LEFT JOIN inventory_locations l ON l.id=s.location_id LEFT JOIN inventory_batches b ON b.id=s.batch_id WHERE s.id=$1`,[req.params.id]))[0];
  if(!s)return res.status(404).json({error:'Serialized unit not found'});
  const [history,movements,orderLinks,saleLinks,warrantyLinks,returnLinks]=await Promise.all([
    q(`SELECT h.*,fl.name from_location_name,tl.name to_location_name,u.email actor_email FROM serialized_unit_status_history h LEFT JOIN inventory_locations fl ON fl.id=h.from_location_id LEFT JOIN inventory_locations tl ON tl.id=h.to_location_id LEFT JOIN users u ON u.id=h.actor_id WHERE h.serialized_unit_id=$1 ORDER BY h.created_at DESC LIMIT 200`,[s.id]),
    q(`SELECT m.*,l.name location_name,u.email actor_email FROM inventory_movements m JOIN inventory_locations l ON l.id=m.location_id LEFT JOIN users u ON u.id=m.actor_id WHERE m.variant_id=$1 AND (m.reference_id=$2 OR m.reason ILIKE $3) ORDER BY m.created_at DESC LIMIT 100`,[s.variant_id,s.id,`%${s.serial_number||s.imei1||s.imei2||'SERIAL'}%`]),
    q(`SELECT os.id assignment_id,ol.id order_line_id,o.id order_id,o.order_no,o.status order_status,os.assigned_at,os.assigned_by FROM order_serial_units os JOIN order_lines ol ON ol.id=os.order_line_id JOIN orders o ON o.id=ol.order_id WHERE os.serialized_unit_id=$1 ORDER BY os.assigned_at DESC LIMIT 50`,[s.id]),
    q(`SELECT ss.sale_line_id,s.id sale_id,s.sale_no,s.status sale_status,s.created_at FROM sale_serial_units ss JOIN sale_lines sl ON sl.id=ss.sale_line_id JOIN sales s ON s.id=sl.sale_id WHERE ss.serialized_unit_id=$1 ORDER BY s.created_at DESC LIMIT 50`,[s.id]),
    q(`SELECT w.id,w.claim_no,w.status,w.created_at,w.updated_at FROM warranty_claims w WHERE w.serialized_unit_id=$1 ORDER BY w.created_at DESC LIMIT 50`,[s.id]),
    q(`SELECT r.id,r.return_no,r.status,r.created_at,rl.id return_line_id FROM return_lines rl JOIN return_requests r ON r.id=rl.return_id WHERE rl.serialized_unit_id=$1 ORDER BY r.created_at DESC LIMIT 50`,[s.id])
  ]);
  res.json({unit:s,history,movements,links:{orders:orderLinks,sales:saleLinks,warranty:warrantyLinks,returns:returnLinks}});
});

