app.post('/api/inventory/stocktakes',auth,need('inventory.stocktake'),async(req,res)=>{const b=req.body||{};if(!b.locationId)return res.status(400).json({error:'Location is required'});const client=await pool.connect();try{await client.query('BEGIN');const st=(await client.query('INSERT INTO inventory_stocktakes(stocktake_no,location_id,status,notes,created_by) VALUES($1,$2,\'In Progress\',$3,$4) RETURNING *',[inventoryNo('STK'),b.locationId,String(b.notes||''),req.user.id])).rows[0];const stock=(await client.query(`SELECT v.id,v.sku,v.variant_name,p.name product_name,COALESCE(ib.on_hand,0) system_qty FROM product_variants v JOIN products p ON p.id=v.product_id LEFT JOIN inventory_balances ib ON ib.variant_id=v.id AND ib.location_id=$1 WHERE v.status='Active' AND v.serialized=false ORDER BY p.name,v.sku`,[b.locationId])).rows;for(const row of stock){await client.query('INSERT INTO inventory_stocktake_lines(stocktake_id,variant_id,system_qty) VALUES($1,$2,$3)',[st.id,row.id,row.system_qty])}const serialized=(await client.query(`SELECT s.id,s.variant_id,s.serial_number,s.imei1,s.imei2 FROM serialized_units s WHERE s.location_id=$1 AND s.status IN ('In Stock','Reserved','Service') ORDER BY s.variant_id,s.created_at`,[b.locationId])).rows;for(const su of serialized){await client.query(`INSERT INTO inventory_stocktake_serial_lines(stocktake_id,serialized_unit_id,variant_id,expected_present,serial_snapshot) VALUES($1,$2,$3,true,$4) ON CONFLICT(stocktake_id,serialized_unit_id) DO NOTHING`,[st.id,su.id,su.variant_id,JSON.stringify({serialNumber:su.serial_number,imei1:su.imei1,imei2:su.imei2})])}await client.query('COMMIT');await audit(req.user,'STOCKTAKE_STARTED','InventoryStocktake',st.id,`Started stocktake ${st.stocktake_no}`,null,st,req.req);res.status(201).json(st)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.get('/api/inventory/stocktakes/:id',auth,need('inventory.view'),async(req,res)=>{const st=(await q(`SELECT s.*,l.name location_name FROM inventory_stocktakes s JOIN inventory_locations l ON l.id=s.location_id WHERE s.id=$1`,[req.params.id]))[0];if(!st)return res.status(404).json({error:'Stocktake not found'});st.lines=await q(`SELECT sl.*,v.sku,v.variant_name,p.name product_name FROM inventory_stocktake_lines sl JOIN product_variants v ON v.id=sl.variant_id JOIN products p ON p.id=v.product_id WHERE sl.stocktake_id=$1 ORDER BY p.name,v.sku`,[st.id]);res.json(st)});
app.patch('/api/inventory/stocktakes/:id/count',auth,need('inventory.stocktake'),async(req,res)=>{const st=(await q("SELECT * FROM inventory_stocktakes WHERE id=$1 AND status='In Progress'",[req.params.id]))[0];if(!st)return res.status(404).json({error:'Active stocktake not found'});const lines=Array.isArray(req.body?.lines)?req.body.lines:[];const client=await pool.connect();try{await client.query('BEGIN');for(const line of lines){if(line.countedQty===undefined||Number(line.countedQty)<0)throw new Error('Counted quantity must be zero or greater');const r=(await client.query('UPDATE inventory_stocktake_lines SET counted_qty=$1,variance=$1-system_qty,reason=$2,counted_at=now() WHERE stocktake_id=$3 AND variant_id=$4 RETURNING *',[Number(line.countedQty),String(line.reason||''),st.id,line.variantId])).rows[0];if(!r)throw new Error('Stocktake line not found')}await client.query('COMMIT');res.json({ok:true})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.patch('/api/inventory/stocktakes/:id/count-serialized',auth,need('inventory.stocktake'),async(req,res)=>{const lines=Array.isArray(req.body?.lines)?req.body.lines:[];const client=await pool.connect();try{await client.query('BEGIN');const st=(await client.query("SELECT * FROM inventory_stocktakes WHERE id=$1 AND status='In Progress' FOR UPDATE",[req.params.id])).rows[0];if(!st)throw new Error('Active stocktake not found');for(const line of lines){if(!line.serialLineId||typeof line.countedPresent!=='boolean')throw new Error('Serialized stocktake line and counted presence are required');const r=(await client.query('UPDATE inventory_stocktake_serial_lines SET counted_present=$1,reason=$2,counted_at=now() WHERE id=$3 AND stocktake_id=$4 RETURNING *',[line.countedPresent,String(line.reason||''),line.serialLineId,st.id])).rows[0];if(!r)throw new Error('Serialized stocktake line not found')}await client.query('COMMIT');res.json({ok:true,updated:lines.length})}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
app.post('/api/inventory/stocktakes/:id/scan-serialized',auth,need('inventory.stocktake'),async(req,res)=>{const b=req.body||{};const key=String(b.serialNumber||b.imei1||b.imei2||'').trim();if(!b.variantId||!key)return res.status(400).json({error:'Variant and serial/IMEI are required'});const client=await pool.connect();try{await client.query('BEGIN');const st=(await client.query("SELECT * FROM inventory_stocktakes WHERE id=$1 AND status='In Progress' FOR UPDATE",[req.params.id])).rows[0];if(!st)throw new Error('Active stocktake not found');const v=(await client.query('SELECT * FROM product_variants WHERE id=$1',[b.variantId])).rows[0];if(!v||!v.serialized)throw new Error('Variant is not serialized');const ids=[b.serialNumber,b.imei1,b.imei2,b.barcode,b.qrCode].map(v=>String(v||'').trim()).filter(Boolean);if(!ids.length)throw new Error('A serial, IMEI, barcode or QR value is required');if(new Set(ids.map(v=>v.toLowerCase())).size!==ids.length)throw new Error('The same identifier cannot be entered twice');const su=(await client.query('SELECT * FROM serialized_units WHERE serial_number=ANY($1) OR imei1=ANY($1) OR imei2=ANY($1) OR barcode=ANY($1) OR qr_code=ANY($1) FOR UPDATE',[ids])).rows[0];let unit=su;if(!unit){await client.query("SELECT set_config('app.actor_id',$1,true)",[req.user.id]);unit=(await client.query("INSERT INTO serialized_units(variant_id,location_id,serial_number,imei1,imei2,barcode,qr_code,status,unit_cost,received_at) VALUES($1,$2,$3,$4,$5,$6,$7,'In Stock',$8,now()) RETURNING *",[v.id,st.location_id,b.serialNumber||null,b.imei1||null,b.imei2||null,b.barcode||null,b.qrCode||null,Number(v.cost_price||0)])).rows[0];await client.query("UPDATE serialized_unit_status_history SET reason='Physical unit discovered during stocktake',source_type='InventoryStocktake',source_id=$1 WHERE id=(SELECT id FROM serialized_unit_status_history WHERE serialized_unit_id=$2 ORDER BY created_at DESC,id DESC LIMIT 1)",[st.id,unit.id]);}else if(unit.location_id!==st.location_id)throw new Error('Serialized unit belongs to another location');const row=(await client.query(`INSERT INTO inventory_stocktake_serial_lines(stocktake_id,serialized_unit_id,variant_id,expected_present,counted_present,serial_snapshot,reason,counted_at) VALUES($1,$2,$3,false,true,$4,'Found during stocktake',now()) ON CONFLICT(stocktake_id,serialized_unit_id) DO UPDATE SET counted_present=true,counted_at=now(),reason='Found during stocktake' RETURNING *`,[st.id,unit.id,v.id,JSON.stringify({serialNumber:unit.serial_number,imei1:unit.imei1,imei2:unit.imei2})])).rows[0];await client.query('COMMIT');res.status(201).json(row)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

app.post('/api/inventory/stocktakes/:id/finalize',auth,need('inventory.stocktake'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const st=(await client.query("SELECT * FROM inventory_stocktakes WHERE id=$1 AND status='In Progress' FOR UPDATE",[req.params.id])).rows[0];if(!st)throw new Error('Active stocktake not found');const lines=(await client.query('SELECT sl.*,v.cost_price,v.serialized,COALESCE((SELECT ib.on_hand FROM inventory_balances ib WHERE ib.variant_id=sl.variant_id AND ib.location_id=$2),0) current_qty FROM inventory_stocktake_lines sl JOIN product_variants v ON v.id=sl.variant_id WHERE sl.stocktake_id=$1 FOR UPDATE',[st.id,st.location_id])).rows;if(!lines.length)throw new Error('Stocktake has no lines');for(const line of lines){if(line.counted_qty===null)throw new Error('Every stocktake line must be counted before finalization');const currentQty=Number(line.current_qty);const variance=Number(line.counted_qty)-currentQty;await client.query('UPDATE inventory_stocktake_lines SET system_qty=$1,variance=$2 WHERE id=$3',[currentQty,variance,line.id]);if(variance!==0)await changeStock(client,{variantId:line.variant_id,locationId:st.location_id,delta:variance,type:variance>0?'STOCKTAKE_IN':'STOCKTAKE_OUT',actorId:req.user.id,referenceType:'InventoryStocktake',referenceId:st.id,reason:String(line.reason||'Stocktake reconciliation'),unitCost:Number(line.cost_price||0)});}const serialLines=(await client.query(`SELECT ssl.*,s.location_id,s.status,v.cost_price FROM inventory_stocktake_serial_lines ssl JOIN serialized_units s ON s.id=ssl.serialized_unit_id JOIN product_variants v ON v.id=ssl.variant_id WHERE ssl.stocktake_id=$1 FOR UPDATE`,[st.id])).rows;for(const sl of serialLines){if(sl.counted_present===null)throw new Error('Every serialized stocktake line must be counted');if(sl.expected_present&&!sl.counted_present){await changeStock(client,{variantId:sl.variant_id,locationId:st.location_id,delta:-1,type:'STOCKTAKE_OUT',actorId:req.user.id,referenceType:'InventoryStocktake',referenceId:st.id,reason:'Serialized unit missing during stocktake',unitCost:Number(sl.cost_price||0)});await transitionSerializedUnit(client,{unitId:sl.serialized_unit_id,toStatus:'Lost',actorId:req.user.id,reason:'Serialized unit missing during stocktake',sourceType:'InventoryStocktake',sourceId:st.id,clearLocation:true})}else if(!sl.expected_present&&sl.counted_present){await changeStock(client,{variantId:sl.variant_id,locationId:st.location_id,delta:1,type:'STOCKTAKE_IN',actorId:req.user.id,referenceType:'InventoryStocktake',referenceId:st.id,reason:'Serialized unit found during stocktake',unitCost:Number(sl.cost_price||0)});await transitionSerializedUnit(client,{unitId:sl.serialized_unit_id,toStatus:'In Stock',locationId:st.location_id,actorId:req.user.id,reason:'Serialized unit found during stocktake',sourceType:'InventoryStocktake',sourceId:st.id})}}const done=(await client.query("UPDATE inventory_stocktakes SET status='Completed',completed_by=$1,completed_at=now() WHERE id=$2 RETURNING *",[req.user.id,st.id])).rows[0];await client.query('COMMIT');await audit(req.user,'STOCKTAKE_COMPLETED','InventoryStocktake',done.id,`Completed stocktake ${done.stocktake_no}`,st,done,req.req);res.json(done)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});
