app.post('/api/inventory/incidents',auth,need('inventory.incidents'),async(req,res)=>{const b=req.body||{};if(!['Damage','Loss','Found','Return'].includes(b.type)||!b.locationId||!b.variantId||!(Number(b.quantity)>0)||!String(b.reason||'').trim())return res.status(400).json({error:'Type, location, variant, positive quantity and reason are required'});const r=(await q('INSERT INTO inventory_incidents(incident_no,incident_type,location_id,variant_id,quantity,serials,reason,created_by) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[inventoryNo('INC'),b.type,b.locationId,b.variantId,Number(b.quantity),JSON.stringify(Array.isArray(b.serials)?b.serials:[]),String(b.reason).trim(),req.user.id]))[0];await audit(req.user,'INVENTORY_INCIDENT_CREATED','InventoryIncident',r.id,`Created ${r.incident_type.toLowerCase()} incident ${r.incident_no}`,null,r,req.req);res.status(201).json(r)});
app.patch('/api/inventory/incidents/:id/resolve',auth,need('inventory.incidents'),async(req,res)=>{const client=await pool.connect();try{await client.query('BEGIN');const i=(await client.query("SELECT * FROM inventory_incidents WHERE id=$1 AND status='Open' FOR UPDATE",[req.params.id])).rows[0];if(!i)throw new Error('Open incident not found');const v=(await client.query('SELECT * FROM product_variants WHERE id=$1',[i.variant_id])).rows[0];if(!v)throw new Error('Variant not found');let delta=0,type='';if(i.incident_type==='Damage'||i.incident_type==='Loss'){delta=-Number(i.quantity);type=i.incident_type==='Damage'?'DAMAGE':'LOSS'}else{delta=Number(i.quantity);type=i.incident_type==='Found'?'FOUND':'RETURN'}await changeStock(client,{variantId:i.variant_id,locationId:i.location_id,delta,type,actorId:req.user.id,referenceType:'InventoryIncident',referenceId:i.id,reason:String(req.body?.resolutionNotes||i.reason),unitCost:Number(v.cost_price||0)});const serials=Array.isArray(i.serials)?i.serials:[];for(const sn of serials){const x=typeof sn==='string'?{serialNumber:sn}:sn;const found=(await client.query('SELECT id FROM serialized_units WHERE variant_id=$1 AND (serial_number=$2 OR imei1=$3 OR imei2=$4) FOR UPDATE',[i.variant_id,x.serialNumber||'',x.imei1||'',x.imei2||''])).rows[0];if(['Damage','Loss'].includes(i.incident_type)){if(!found)throw new Error('Serialized unit not found for incident');await transitionSerializedUnit(client,{unitId:found.id,toStatus:i.incident_type==='Damage'?'Damaged':'Lost',actorId:req.user.id,reason:String(req.body?.resolutionNotes||i.reason),sourceType:'InventoryIncident',sourceId:i.id,clearLocation:true})}else if(found){await transitionSerializedUnit(client,{unitId:found.id,toStatus:i.incident_type==='Found'?'In Stock':'Returned',locationId:i.location_id,actorId:req.user.id,reason:String(req.body?.resolutionNotes||i.reason),sourceType:'InventoryIncident',sourceId:i.id})}else{await client.query("SELECT set_config('app.actor_id',$1,true)",[req.user.id]);const created=(await client.query('INSERT INTO serialized_units(variant_id,location_id,serial_number,imei1,imei2,status,unit_cost,received_at) VALUES($1,$2,$3,$4,$5,$6,$7,now()) RETURNING id',[i.variant_id,i.location_id,x.serialNumber||null,x.imei1||null,x.imei2||null,i.incident_type==='Found'?'In Stock':'Returned',Number(v.cost_price||0)])).rows[0];await client.query("UPDATE serialized_unit_status_history SET reason=$1,source_type='InventoryIncident',source_id=$2 WHERE id=(SELECT id FROM serialized_unit_status_history WHERE serialized_unit_id=$3 ORDER BY created_at DESC,id DESC LIMIT 1)",[String(req.body?.resolutionNotes||i.reason),i.id,created.id]);}}const r=(await client.query("UPDATE inventory_incidents SET status='Resolved',resolution_notes=$1,resolved_by=$2,resolved_at=now() WHERE id=$3 RETURNING *",[String(req.body?.resolutionNotes||''),req.user.id,i.id])).rows[0];await client.query('COMMIT');await audit(req.user,'INVENTORY_INCIDENT_RESOLVED','InventoryIncident',r.id,`Resolved ${r.incident_no}`,i,r,req.req);res.json(r)}catch(e){await client.query('ROLLBACK');res.status(400).json({error:e.message})}finally{client.release()}});

