// Public customer authentication. Customer identity is separate from internal staff authentication.
app.get('/api/public/auth/me',async(req,res)=>{
  const c=await publicAuthenticatedCustomer(req); if(!c)return res.status(401).json({authenticated:false});
  const sessions=await q("SELECT id,created_at,last_used_at,expires_at,user_agent FROM customer_auth_sessions WHERE customer_id=$1 AND revoked_at IS NULL AND expires_at>now() ORDER BY last_used_at DESC",[c.id]);
  res.setHeader('Cache-Control','no-store, max-age=0');res.json({authenticated:true,customer:customerPublicPayload(c),csrf:parseCookies(req).amaal_customer_csrf||'',sessions});
});
app.post('/api/public/auth/register',async(req,res)=>{
  const b=req.body||{},name=String(b.name||'').trim().slice(0,160),email=safeCustomerIdentifier(b.email),phone=normalizeCustomerPhone(b.phone),password=String(b.password||'');
  if(!name||(!email&&!phone)||!password)return res.status(400).json({error:'Name, email or phone, and password are required.'});
  const pErr=passwordError(password,baseSettings);if(pErr)return res.status(400).json({error:pErr});
  const key=`register:${req.ip}:${email||phone}`;if(!customerRateLimit(key,5,15*60*1000))return res.status(429).json({error:'Too many account creation attempts. Please try again later.'});
  const client=await pool.connect();try{await client.query('BEGIN');
    const matches=await client.query("SELECT id,name,email,phone FROM customers WHERE status<>'Anonymized' AND ((NULLIF($1,'') IS NOT NULL AND lower(email)=lower($1)) OR (NULLIF($2,'') IS NOT NULL AND phone=$2)) ORDER BY created_at DESC LIMIT 2 FOR UPDATE",[email,phone]);
    if(matches.rows.length>1)throw new Error('More than one customer record matches those details. Please contact Amaal support.');
    let c=matches.rows[0];
    if(!c){c=(await client.query("INSERT INTO customers(customer_no,name,customer_type,email,phone,country_code,preferred_currency,status,notes) VALUES($1,$2,'Individual',$3,$4,'UG','UGX','Active','Created through Amaal customer account registration') RETURNING id,customer_no,name,email,phone,alternate_phone,city,region,country_code,preferred_currency,status",[`CUS-${new Date().getFullYear()}-${crypto.randomBytes(4).toString('hex').toUpperCase()}`,name,email,phone])).rows[0];await client.query('INSERT INTO customer_balances(customer_id,balance,credit_limit) VALUES($1,0,0) ON CONFLICT DO NOTHING',[c.id]);}
    else if((email&&c.email&&c.email.toLowerCase()!==email)||(phone&&c.phone&&c.phone!==phone))throw new Error('Those details do not match the existing customer record.');
    const existing=(await client.query('SELECT id FROM customer_credentials WHERE customer_id=$1',[c.id])).rows[0];if(existing)throw new Error('An account already exists for this customer. Please sign in.');
    const hash=await bcrypt.hash(password,12);await client.query('INSERT INTO customer_credentials(customer_id,password_hash) VALUES($1,$2)',[c.id,hash]);
    const session=await issueCustomerSession(client,c.id,req,Boolean(b.remember));await client.query('COMMIT');setCustomerSessionCookies(res,session);res.setHeader('Cache-Control','no-store, max-age=0');res.status(201).json({customer:customerPublicPayload(c),csrf:session.csrf});
  }catch(e){try{await client.query('ROLLBACK')}catch{}res.status(String(e.message).includes('already exists')?409:400).json({error:e.message||'Unable to create your account.'})}finally{client.release()}
});
app.post('/api/public/auth/login',async(req,res)=>{
  const identifier=String(req.body?.identifier||'').trim(), password=String(req.body?.password||''), key=`login:${req.ip}:${safeCustomerIdentifier(identifier)}`;
  if(!identifier||!password)return res.status(400).json({error:'Email or phone and password are required.'});
  if(!customerRateLimit(key,10,15*60*1000))return res.status(429).json({error:'Too many sign-in attempts. Please try again later.'});
  const normalized=safeCustomerIdentifier(identifier), phone=normalizeCustomerPhone(identifier);
  const c=(await q("SELECT c.*,cc.password_hash,cc.failed_attempts,cc.locked_until FROM customers c JOIN customer_credentials cc ON cc.customer_id=c.id WHERE c.status<>'Anonymized' AND (lower(c.email)=lower($1) OR c.phone=$2) ORDER BY c.created_at DESC LIMIT 1",[normalized,phone]))[0];
  if(!c)return res.status(401).json({error:'Invalid sign-in details.'});
  if(c.status==='Blocked')return res.status(403).json({error:'This customer account is unavailable. Please contact Amaal support.'});
  if(c.locked_until&&new Date(c.locked_until)>new Date())return res.status(423).json({error:'This account is temporarily locked. Please try again later.'});
  const ok=await bcrypt.compare(password,c.password_hash);if(!ok){const attempts=Number(c.failed_attempts||0)+1,locked=attempts>=5?new Date(Date.now()+15*60000):null;await q('UPDATE customer_credentials SET failed_attempts=$1,locked_until=$2,updated_at=now() WHERE customer_id=$3',[attempts,locked,c.id]);await q('INSERT INTO customer_auth_events(customer_id,identifier,success,reason,ip,user_agent) VALUES($1,$2,false,$3,$4,$5)',[c.id,normalized,'Invalid credentials',req.ip,req.get('user-agent')||'']).catch(()=>{});return res.status(401).json({error:locked?'Too many attempts. Your account is temporarily locked.':'Invalid sign-in details.'});}
  const client=await pool.connect();try{await client.query('BEGIN');await client.query('UPDATE customer_credentials SET failed_attempts=0,locked_until=NULL,last_login_at=now(),updated_at=now() WHERE customer_id=$1',[c.id]);const session=await issueCustomerSession(client,c.id,req,Boolean(req.body?.remember));await client.query('INSERT INTO customer_auth_events(customer_id,identifier,success,reason,ip,user_agent) VALUES($1,$2,true,$3,$4,$5)',[c.id,normalized,'Customer signed in',req.ip,req.get('user-agent')||'']);await client.query('COMMIT');customerLoginAttempts.delete(key);setCustomerSessionCookies(res,session);res.setHeader('Cache-Control','no-store, max-age=0');res.json({customer:customerPublicPayload(c),csrf:session.csrf});}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(503).json({error:'Sign-in is temporarily unavailable.'})}finally{client.release()}
});
app.post('/api/public/auth/claim',async(req,res)=>{
  const legacy=String(req.get('X-Amaal-Customer-Token')||'').trim(), password=String(req.body?.password||''),name=String(req.body?.name||'').trim();
  if(!legacy||!password)return res.status(400).json({error:'Your Amaal access token and a new password are required.'});const pErr=passwordError(password,baseSettings);if(pErr)return res.status(400).json({error:pErr});
  const hash=customerSessionHash(legacy);const client=await pool.connect();try{await client.query('BEGIN');const c=(await client.query("SELECT c.* FROM customer_access_tokens t JOIN customers c ON c.id=t.customer_id WHERE t.token_hash=$1 AND t.expires_at>now() AND c.status='Active' FOR UPDATE",[hash])).rows[0];if(!c)throw new Error('That account access token has expired or is invalid.');const existing=(await client.query('SELECT id FROM customer_credentials WHERE customer_id=$1',[c.id])).rows[0];if(existing)throw new Error('A password is already set. Please sign in instead.');if(name)await client.query('UPDATE customers SET name=$1,updated_at=now() WHERE id=$2',[name.slice(0,160),c.id]);await client.query('INSERT INTO customer_credentials(customer_id,password_hash) VALUES($1,$2)',[c.id,await bcrypt.hash(password,12)]);await client.query('DELETE FROM customer_access_tokens WHERE customer_id=$1',[c.id]);const session=await issueCustomerSession(client,c.id,req,Boolean(req.body?.remember));await client.query('COMMIT');setCustomerSessionCookies(res,session);res.json({customer:customerPublicPayload({...c,name:name||c.name}),csrf:session.csrf});}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(400).json({error:e.message||'Unable to activate this account.'})}finally{client.release()}
});
app.post('/api/public/auth/logout',async(req,res)=>{const c=await publicAuthenticatedCustomer(req);const cookies=parseCookies(req);if(c?.session_id)await q('UPDATE customer_auth_sessions SET revoked_at=now() WHERE id=$1',[c.session_id]).catch(()=>{});clearCustomerSessionCookies(res);res.json({ok:true});});
app.post('/api/public/auth/logout-all',async(req,res)=>{const c=await publicAuthenticatedCustomer(req);if(!c)return res.status(401).json({error:'You are not signed in.'});if(!(await requireCustomerCsrf(req,res)))return;await q('UPDATE customer_auth_sessions SET revoked_at=now() WHERE customer_id=$1 AND revoked_at IS NULL',[c.id]);clearCustomerSessionCookies(res);res.json({ok:true});});
app.delete('/api/public/auth/sessions/:id',async(req,res)=>{const c=await publicAuthenticatedCustomer(req);if(!c)return res.status(401).json({error:'You are not signed in.'});if(!(await requireCustomerCsrf(req,res)))return;const x=(await q('UPDATE customer_auth_sessions SET revoked_at=now() WHERE id=$1 AND customer_id=$2 AND revoked_at IS NULL RETURNING id',[req.params.id,c.id]))[0];if(!x)return res.status(404).json({error:'Session not found.'});res.json({ok:true});});
app.patch('/api/public/auth/profile',async(req,res)=>{const c=await publicAuthenticatedCustomer(req);if(!c)return res.status(401).json({error:'You are not signed in.'});if(!(await requireCustomerCsrf(req,res)))return;const b=req.body||{},name=String(b.name||'').trim().slice(0,160),email=safeCustomerIdentifier(b.email),phone=normalizeCustomerPhone(b.phone),currentPassword=String(b.currentPassword||'');if(!name||(!email&&!phone)||!currentPassword)return res.status(400).json({error:'Name, contact detail and current password are required.'});const cred=(await q('SELECT password_hash FROM customer_credentials WHERE customer_id=$1',[c.id]))[0];if(!cred||!(await bcrypt.compare(currentPassword,cred.password_hash)))return res.status(400).json({error:'Current password is incorrect.'});try{const conflict=(await q("SELECT id FROM customers WHERE id<>$1 AND status<>'Anonymized' AND ((NULLIF($2,'') IS NOT NULL AND lower(email)=lower($2)) OR (NULLIF($3,'') IS NOT NULL AND phone=$3)) LIMIT 1",[c.id,email,phone]))[0];if(conflict)return res.status(409).json({error:'Those contact details are already used by another customer.'});const out=(await q('UPDATE customers SET name=$1,email=$2,phone=$3,city=COALESCE(NULLIF($4,\'\'),city),region=COALESCE(NULLIF($5,\'\'),region),updated_at=now() WHERE id=$6 RETURNING *',[name,email,phone,String(b.city||''),String(b.region||''),c.id]))[0];res.json({customer:customerPublicPayload(out)});}catch(e){res.status(400).json({error:'Unable to update your profile.'})}});
app.post('/api/public/auth/password',async(req,res)=>{const c=await publicAuthenticatedCustomer(req);if(!c)return res.status(401).json({error:'You are not signed in.'});if(!(await requireCustomerCsrf(req,res)))return;const current=String(req.body?.currentPassword||''),next=String(req.body?.newPassword||'');if(!current||!next)return res.status(400).json({error:'Current and new passwords are required.'});const pErr=passwordError(next,baseSettings);if(pErr)return res.status(400).json({error:pErr});const cred=(await q('SELECT password_hash FROM customer_credentials WHERE customer_id=$1',[c.id]))[0];if(!cred||!(await bcrypt.compare(current,cred.password_hash)))return res.status(400).json({error:'Current password is incorrect.'});if(await bcrypt.compare(next,cred.password_hash))return res.status(400).json({error:'Choose a different password.'});const hash=await bcrypt.hash(next,12);await q('UPDATE customer_credentials SET password_hash=$1,password_changed_at=now(),updated_at=now() WHERE customer_id=$2',[hash,c.id]);await q('UPDATE customer_auth_sessions SET revoked_at=now() WHERE customer_id=$1 AND id<>$2',[c.id,c.session_id]);res.json({ok:true});});
app.post('/api/public/auth/recover-with-access-token',async(req,res)=>{req.headers['x-amaal-customer-token']=String(req.body?.accessToken||'');return res.status(410).json({error:'Use the account activation flow with your original Amaal access token.'});});

// Public storefront checkout: guest checkout only. It uses the same authoritative product pricing,
// inventory reservation and order tables as the Business Console. No product CRUD is exposed here.
const publicCheckoutRate=new Map();
function publicCheckoutLimit(req,res,next){
  const key=`${req.ip}:checkout`; const now=Date.now(); const v=publicCheckoutRate.get(key)||{count:0,resetAt:now+60000};
  if(v.resetAt<=now){v.count=0;v.resetAt=now+60000;} if(v.count>=20)return res.status(429).json({error:'Too many checkout attempts. Please wait a moment.'}); v.count++; publicCheckoutRate.set(key,v); next();
}
async function issueCustomerToken(client,customerId){const raw=crypto.randomBytes(32).toString('base64url');const hash=crypto.createHash('sha256').update(raw).digest('hex');await client.query("INSERT INTO customer_access_tokens(customer_id,token_hash,expires_at) VALUES($1,$2,now()+interval '180 days')",[customerId,hash]);return raw;}
async function publicCustomer(req){const raw=String(req.get('X-Amaal-Customer-Token')||'').trim();if(!raw||raw.length<32||raw.length>200)return null;const hash=crypto.createHash('sha256').update(raw).digest('hex');const rows=await q("SELECT c.* FROM customer_access_tokens t JOIN customers c ON c.id=t.customer_id WHERE t.token_hash=$1 AND t.expires_at>now() AND c.status<>'Anonymized'",[hash]);const c=rows[0]||null;if(c){q('UPDATE customer_access_tokens SET last_used_at=now() WHERE token_hash=$1',[hash]).catch(()=>{});}return c;}
function customerCookieOptions(maxAge=604800){return `Path=/; HttpOnly; Secure; SameSite=None; Max-Age=${Math.max(300,Number(maxAge)||604800)}`}
function customerCsrfCookie(maxAge=604800){return `Path=/; Secure; SameSite=None; Max-Age=${Math.max(300,Number(maxAge)||604800)}`}
function safeCustomerIdentifier(value){return String(value||'').trim().toLowerCase().slice(0,180)}
function customerSessionHash(raw){return crypto.createHash('sha256').update(String(raw||'')).digest('hex')}
function getOrCreateCustomerDeviceId(req){const c=parseCookies(req);return c.amaal_customer_device||crypto.randomBytes(32).toString('base64url')}
async function issueCustomerSession(client,customerId,req,remember=false){
  const raw=crypto.randomBytes(48).toString('base64url');
  const hash=customerSessionHash(raw); const csrf=crypto.randomBytes(24).toString('base64url');
  const csrfHash=customerSessionHash(csrf); const deviceId=getOrCreateCustomerDeviceId(req); const dHash=deviceHash(deviceId);
  const days=remember?30:7;
  await client.query("INSERT INTO customer_auth_sessions(customer_id,token_hash,csrf_hash,device_hash,user_agent_hash,expires_at,ip,user_agent) VALUES($1,$2,$3,$4,$5,now()+($6 || ' days')::interval,$7,$8)",[customerId,hash,csrfHash,dHash,userAgentHash(req.get('user-agent')||''),days,req.ip,req.get('user-agent')||'']);
  return {raw,csrf,deviceId,maxAge:days*86400};
}
async function publicAuthenticatedCustomer(req){
  const cookies=parseCookies(req); const raw=String(cookies.amaal_customer_session||'').trim();
  if(raw.length<40||raw.length>200)return null;
  const hash=customerSessionHash(raw);
  const rows=await q("SELECT c.*,s.id session_id,s.csrf_hash,s.device_hash,s.user_agent_hash FROM customer_auth_sessions s JOIN customers c ON c.id=s.customer_id WHERE s.token_hash=$1 AND s.revoked_at IS NULL AND s.expires_at>now() AND c.status='Active'",[hash]);
  const c=rows[0]||null; if(!c)return null;
  const deviceId=cookies.amaal_customer_device||'';
  if(c.device_hash&&(!deviceId||deviceHash(deviceId)!==c.device_hash))return null;
  if(c.user_agent_hash&&userAgentHash(req.get('user-agent')||'')!==c.user_agent_hash)return null;
  await q('UPDATE customer_auth_sessions SET last_used_at=now() WHERE id=$1',[c.session_id]).catch(()=>{});
  return c;
}
async function publicAccountCustomer(req){return (await publicAuthenticatedCustomer(req))||await publicCustomer(req)}
function setCustomerSessionCookies(res,session){
  res.setHeader('Set-Cookie',[
    `amaal_customer_session=${encodeURIComponent(session.raw)}; ${customerCookieOptions(session.maxAge)}`,
    `amaal_customer_csrf=${encodeURIComponent(session.csrf)}; ${customerCsrfCookie(session.maxAge)}`,
    `amaal_customer_device=${encodeURIComponent(session.deviceId)}; ${customerCookieOptions(15552000)}`
  ]);
}
function clearCustomerSessionCookies(res){res.setHeader('Set-Cookie',['amaal_customer_session=; Path=/; HttpOnly; Secure; SameSite=None; Max-Age=0','amaal_customer_csrf=; Path=/; Secure; SameSite=None; Max-Age=0','amaal_customer_device=; Path=/; HttpOnly; Secure; SameSite=None; Max-Age=0']);}
async function requireCustomerCsrf(req,res){
  const cookies=parseCookies(req); const raw=String(cookies.amaal_customer_session||'');
  if(!raw)return true;
  const expected=String(cookies.amaal_customer_csrf||''); const supplied=String(req.get('X-Amaal-Customer-CSRF')||'');
  if(!expected||!supplied||expected.length!==supplied.length||!crypto.timingSafeEqual(Buffer.from(expected),Buffer.from(supplied))) {res.status(403).json({error:'Security check failed. Please refresh and try again.'});return false;}
  return true;
}

const customerLoginAttempts=new Map();
function customerRateLimit(key,limit=8,windowMs=15*60*1000){const now=Date.now();const x=customerLoginAttempts.get(key)||{count:0,resetAt:now+windowMs};if(x.resetAt<=now){x.count=0;x.resetAt=now+windowMs;}if(x.count>=limit)return false;x.count++;customerLoginAttempts.set(key,x);return true;}
function normalizeCustomerPhone(v){return String(v||'').replace(/[^0-9+]/g,'').trim().slice(0,30)}
function customerPublicPayload(c){return {id:c.id,customerNo:c.customer_no,name:c.name,email:c.email,phone:c.phone,alternatePhone:c.alternate_phone,city:c.city,region:c.region,countryCode:c.country_code,preferredCurrency:c.preferred_currency,status:c.status};}

app.post('/api/public/checkout',publicCheckoutLimit,async(req,res)=>{
  const b=req.body||{}, lines=Array.isArray(b.lines)?b.lines:[];
  const text=v=>String(v??'').trim(); const money=v=>Math.round((Number(v)||0)*100)/100;
  if(!text(b.name)||!text(b.phone)||!lines.length)return res.status(400).json({error:'Name, phone and at least one product are required.'});
  if(text(b.countryCode)&&text(b.countryCode)!=='UG')return res.status(400).json({error:'Amaal currently delivers within Uganda.'});
  if(text(b.paymentMethod)&&!['Mobile Money','Card','Cash'].includes(text(b.paymentMethod)))return res.status(400).json({error:'Unsupported payment method.'});
  const idem=text(req.get('Idempotency-Key')||b.idempotencyKey); const cartId=text(b.cartId); const client=await pool.connect();
  try{
    await client.query('BEGIN');
    if(idem){const existing=(await client.query('SELECT id FROM orders WHERE idempotency_key=$1 FOR SHARE',[idem])).rows[0];if(existing){await client.query('ROLLBACK');const o=(await client.query('SELECT id,order_no,status,payment_status,fulfillment_status,grand_total,currency,shipping_name,shipping_phone,shipping_address,created_at FROM orders WHERE id=$1',[existing.id])).rows[0];const customer=(await client.query('SELECT customer_id FROM orders WHERE id=$1',[existing.id])).rows[0]; const token=customer?.customer_id?await issueCustomerToken(client,customer.customer_id):null; await client.query('COMMIT'); return res.json({order:o,customerToken:token})}}
    const loc=(await client.query("SELECT id,name FROM inventory_locations WHERE status='Active' ORDER BY id LIMIT 1")).rows[0]; if(!loc)throw new Error('Amaal has no active fulfilment location configured.');
    const phone=text(b.phone), email=text(b.email).toLowerCase(), name=text(b.name);
    let customer=(await client.query("SELECT id FROM customers WHERE phone=$1 AND status<>'Anonymized' ORDER BY created_at DESC LIMIT 1 FOR UPDATE",[phone])).rows[0];
    if(!customer){
      customer=(await client.query(`INSERT INTO customers(customer_no,name,customer_type,email,phone,country_code,preferred_currency,address_line1,address_line2,city,region,postal_code,status,notes) VALUES($1,$2,'Individual',$3,$4,'UG','UGX',$5,$6,$7,$8,$9,'Active','Created from public storefront checkout') RETURNING id`,[`CUS-${new Date().getFullYear()}-${crypto.randomBytes(4).toString('hex').toUpperCase()}`,name,email,phone,text(b.addressLine1),text(b.addressLine2),text(b.city),text(b.region),text(b.postalCode)])).rows[0];
      await client.query('INSERT INTO customer_balances(customer_id,balance,credit_limit) VALUES($1,0,0)',[customer.id]);
    } else {
      await client.query('UPDATE customers SET name=$1,email=$2,address_line1=$3,address_line2=$4,city=$5,region=$6,postal_code=$7,updated_at=now() WHERE id=$8',[name,email,text(b.addressLine1),text(b.addressLine2),text(b.city),text(b.region),text(b.postalCode),customer.id]);
    }
    let subtotal=0,tax=0; const prepared=[];
    for(const raw of lines){
      const variantId=text(raw.variantId), lineQty=Math.max(0,Number(raw.quantity)||0); if(!variantId||lineQty<=0||lineQty>100)throw new Error('Every checkout line must contain a valid quantity.');
      const v=(await client.query(`SELECT v.*,p.name product_name FROM product_variants v JOIN products p ON p.id=v.product_id WHERE (v.id=$1 OR v.sku=$1) AND v.status='Active' AND p.status='Active' AND p.website_visibility='Published' FOR SHARE`,[variantId])).rows[0]; if(!v)throw new Error('One of the selected products is no longer available.');
      const effective=(await client.query('SELECT * FROM amaal_effective_variant_price_qty($1,$2,$3,$4)',[v.id,'Retail',lineQty,null])).rows[0];
      const unit=money(effective?.final_price??v.selling_price); if(unit<=0)throw new Error(`${v.product_name} is not yet available for online purchase.`);
      if(v.serialized&&lineQty!==1)throw new Error(`${v.product_name} is limited to one unit per order line.`);
      if(v.track_inventory){const bal=(await client.query('SELECT on_hand,reserved FROM inventory_balances WHERE variant_id=$1 AND location_id=$2 FOR UPDATE',[v.id,loc.id])).rows[0];const available=bal?Number(bal.on_hand)-Number(bal.reserved):0;if(available<lineQty)throw new Error(`Only ${Math.max(0,available)} unit(s) of ${v.product_name} are currently available.`)}
      const tx=money(unit*lineQty*Number(v.tax_rate||0)/100); subtotal=money(subtotal+unit*lineQty); tax=money(tax+tx); prepared.push({v,qty:lineQty,unit,tx});
    }
    const deliveryRegion=text(b.region); const deliveryZone=(await client.query("SELECT fee FROM delivery_zones WHERE status='Active' AND (lower(region)=lower($1) OR lower(name)=lower($1)) ORDER BY fee LIMIT 1",[deliveryRegion])).rows[0]; const shipping=money(deliveryZone?Number(deliveryZone.fee):0); const grand=money(subtotal+tax+shipping); if(grand<=0)throw new Error('Order total must be greater than zero.');
    const orderNo=`WEB-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;
    const o=(await client.query(`INSERT INTO orders(order_no,idempotency_key,customer_id,location_id,status,payment_status,fulfillment_status,subtotal,discount_amount,tax_amount,shipping_amount,grand_total,currency,shipping_name,shipping_phone,shipping_email,shipping_address,notes,created_by) VALUES($1,$2,$3,$4,'Pending Payment','Pending','Unfulfilled',$5,0,$6,$7,$8,'UGX',$9,$10,$11,$12,$13,NULL) RETURNING id,order_no,status,payment_status,fulfillment_status,grand_total,currency,shipping_name,shipping_phone,shipping_address,created_at`,[orderNo,idem||null,customer.id,loc.id,subtotal,tax,shipping,grand,name,phone,email,[text(b.addressLine1),text(b.area),text(b.landmark),text(b.directions),text(b.city),text(b.region),text(b.postalCode)].filter(Boolean).join(', '),[text(b.notes),text(b.deliveryNotes)].filter(Boolean).join(' — ')])).rows[0];
    for(const x of prepared){const line=(await client.query(`INSERT INTO order_lines(order_id,variant_id,quantity,unit_price,discount_amount,tax_rate,tax_amount,line_total,cost_price) VALUES($1,$2,$3,$4,0,$5,$6,$7,$8) RETURNING id`,[o.id,x.v.id,x.qty,x.unit,Number(x.v.tax_rate||0),x.tx,money(x.unit*x.qty+x.tx),money(x.v.cost_price)])).rows[0];if(x.v.track_inventory)await reserveStock(client,{variantId:x.v.id,locationId:loc.id,quantity:x.qty,actorId:null,referenceType:'Order',referenceId:o.id,expiresAt:new Date(Date.now()+24*60*60*1000)});}
    await client.query("INSERT INTO order_status_history(order_id,status,actor_id,notes) VALUES($1,'Pending Payment',NULL,'Order placed through the Amaal storefront')",[o.id]);
    const customerToken=await issueCustomerToken(client,customer.id);
    if(cartId){const guestHash=hashGuestCartToken(guestCartToken(req));const converted=(await client.query("UPDATE commerce_carts SET status='Converted',updated_at=now() WHERE id=$1 AND (customer_id=$2 OR guest_token_hash=$3) RETURNING id",[cartId,customer.id,guestHash||null])).rows[0];if(converted)await client.query('DELETE FROM commerce_cart_items WHERE cart_id=$1',[converted.id]);}
    await client.query('COMMIT');
    res.status(201).json({order:o,customerToken});
  }catch(e){try{await client.query('ROLLBACK')}catch{}res.status(400).json({error:e.message||'Unable to place order.'})}finally{client.release()}
});

app.post('/api/public/orders/payment-intent',publicCheckoutLimit,async(req,res)=>{
  const orderNo=String(req.body?.orderNo||'').trim(), phone=String(req.body?.phone||'').trim(), method=String(req.body?.method||'').trim();
  if(!orderNo||!phone||!['Mobile Money','Card'].includes(method))return res.status(400).json({error:'Order number, phone number and a supported payment method are required.'});
  try{const o=(await q(`SELECT o.id,o.order_no,o.grand_total,o.payment_status,o.status FROM orders o WHERE o.order_no=$1 AND regexp_replace(o.shipping_phone,'[^0-9+]','','g')=regexp_replace($2,'[^0-9+]','','g')`,[orderNo,phone]))[0];if(!o)return res.status(404).json({error:'Order not found.'});if(['Cancelled','Refunded','Delivered','Returned'].includes(o.status))return res.status(400).json({error:'This order cannot receive a new payment.'});const paid=Number((await q("SELECT COALESCE(sum(amount),0)::numeric total FROM order_payments WHERE order_id=$1 AND status='Completed'",[o.id]))[0].total||0);const due=Math.max(0,Number(o.grand_total)-paid);if(due<=0)return res.json({status:'Paid',amount:0});const ref=`WEBPAY-${crypto.randomUUID().slice(0,12).toUpperCase()}`;const p=(await q("INSERT INTO order_payments(order_id,method,amount,reference,status) VALUES($1,$2,$3,$4,'Pending') RETURNING id,method,amount,reference,status,created_at",[o.id,method,due,ref]))[0];res.status(201).json({payment:p,instructions:method==='Mobile Money'?'Amaal will use the configured mobile-money payment flow for this order. Keep your phone nearby.':'Amaal will use the configured secure card gateway for this order.'})}catch(e){res.status(503).json({error:'Payment setup is temporarily unavailable.'})}
});

app.get('/api/public/orders/track',async(req,res)=>{
  const orderNo=String(req.query.orderNo||'').trim(), phone=String(req.query.phone||'').trim(); if(!orderNo||!phone)return res.status(400).json({error:'Order number and phone number are required.'});
  try{const o=(await q(`SELECT o.id,o.order_no,o.status,o.fulfillment_status,o.grand_total,o.currency,o.shipping_name,o.shipping_phone,o.shipping_address,o.created_at,o.updated_at FROM orders o WHERE o.order_no=$1 AND regexp_replace(o.shipping_phone,'[^0-9+]','','g')=regexp_replace($2,'[^0-9+]','','g')`,[orderNo,phone]))[0];if(!o)return res.status(404).json({error:'We could not find an order matching those details.'});const d=(await q(`SELECT shipment_no,method,carrier,tracking_number,status,scheduled_at,delivered_at FROM delivery_shipments WHERE order_id=$1 ORDER BY created_at DESC LIMIT 1`,[o.id]))[0]||null;const deliveryEvents=d?await q('SELECT status,note,location_text,created_at FROM delivery_events WHERE shipment_id=(SELECT id FROM delivery_shipments WHERE order_id=$1 ORDER BY created_at DESC LIMIT 1) ORDER BY created_at',[o.id]):[];const orderEvents=await q("SELECT status,notes AS note,NULL::text AS location_text,created_at FROM order_status_history WHERE order_id=$1 ORDER BY created_at",[o.id]);const events=[...orderEvents,...deliveryEvents].sort((a,b)=>new Date(a.created_at).getTime()-new Date(b.created_at).getTime());res.json({order:o,delivery:d,events})}catch(e){res.status(503).json({error:'Tracking is temporarily unavailable.'})}
});


// Public discovery/search/merchandising helpers.
app.get('/api/public/search/suggestions',async(req,res)=>{const query=String(req.query.q||'').trim().slice(0,100);if(query.length<2)return res.json({suggestions:[],popular:[]});try{const synonyms=(await q("SELECT synonyms FROM search_synonyms WHERE status='Active' AND (lower(term)=$1 OR $1=ANY(SELECT lower(x) FROM unnest(synonyms) x)) LIMIT 1",[query.toLowerCase()]))[0]?.synonyms||[];const terms=[query,...synonyms].slice(0,6);const like=`%${query.replace(/[\%_]/g,'\\$&')}%`;const [products,brands,cats,popular]=await Promise.all([q(`SELECT p.name,p.slug,b.name brand_name,similarity(lower(p.name),lower($1)) score FROM products p LEFT JOIN brands b ON b.id=p.brand_id WHERE p.status='Active' AND p.website_visibility='Published' AND (p.name ILIKE $2 ESCAPE '\\' OR COALESCE(b.name,'') ILIKE $2 ESCAPE '\\' OR similarity(lower(p.name),lower($1))>.28 OR EXISTS(SELECT 1 FROM unnest($3::text[]) term WHERE lower(p.name||' '||coalesce(b.name,'')) LIKE '%'||lower(term)||'%')) ORDER BY p.featured DESC,score DESC,p.name LIMIT 8`,[query,like,terms]),q("SELECT name,slug FROM brands WHERE status='Active' AND website_visibility='Published' AND (name ILIKE $1 ESCAPE '\\' OR similarity(lower(name),lower($2))>.3) ORDER BY similarity(lower(name),lower($2)) DESC,name LIMIT 5",[like,query]),q("SELECT name,slug FROM product_categories WHERE status='Active' AND website_visibility='Published' AND (name ILIKE $1 ESCAPE '\\' OR similarity(lower(name),lower($2))>.3) ORDER BY sort_order,name LIMIT 5",[like,query]),q("SELECT query,count(*)::int count FROM search_events WHERE created_at>now()-interval '30 days' AND lower(query) LIKE lower($1) GROUP BY query ORDER BY count DESC LIMIT 5",[like])]);res.json({suggestions:[...products.map(x=>({type:'product',label:x.name,brand:x.brand_name,slug:x.slug})),...brands.map(x=>({type:'brand',label:x.name,slug:x.slug})),...cats.map(x=>({type:'category',label:x.name,slug:x.slug}))],popular,synonyms});}catch(e){res.status(503).json({suggestions:[],popular:[]})}});
app.post('/api/public/search/event',async(req,res)=>{const query=String(req.body?.query||'').trim().slice(0,160);const resultCount=Math.max(0,Math.min(100000,Number(req.body?.resultCount)||0));if(query.length>=2){q('INSERT INTO search_events(query,result_count) VALUES($1,$2)',[query,resultCount]).catch(()=>{});}res.status(204).end()});
app.get('/api/public/products/:slug/compatible',async(req,res)=>{try{const p=(await q("SELECT id,name,slug FROM products WHERE slug=$1 AND status='Active' AND website_visibility='Published'",[req.params.slug]))[0];if(!p)return res.status(404).json({error:'Product not found.'});const rows=await q(`SELECT r.relation_type,r.confidence,r.notes,tp.slug,tp.name,b.name brand_name,(SELECT CONCAT('/api/public/media/',m.id,'/file?v=',m.checksum_sha256) FROM product_images i JOIN media_assets m ON m.id=i.media_id AND m.status='Active' AND m.visibility='Public' WHERE i.product_id=tp.id ORDER BY i.is_primary DESC,i.sort_order,i.created_at LIMIT 1) image_url,tv.variant_name FROM product_compatibility_rules r JOIN products tp ON tp.id=r.target_product_id LEFT JOIN brands b ON b.id=tp.brand_id LEFT JOIN product_variants tv ON tv.id=r.target_variant_id WHERE r.source_product_id=$1 AND r.status='Active' AND tp.status='Active' AND tp.website_visibility='Published' ORDER BY r.relation_type,r.confidence,tp.name LIMIT 30`,[p.id]);res.json({rows});}catch{res.status(503).json({rows:[]})}});
app.get('/api/public/products/:slug/related',async(req,res)=>{try{const explicit=await q(`SELECT rp.id,rp.slug,rp.name,b.name brand_name,r.relation_type,r.sort_order FROM products p JOIN product_relationships r ON r.product_id=p.id JOIN products rp ON rp.id=r.related_product_id LEFT JOIN brands b ON b.id=rp.brand_id WHERE p.slug=$1 AND rp.status='Active' AND rp.website_visibility='Published' ORDER BY r.relation_type,r.sort_order,rp.name LIMIT 20`,[req.params.slug]);if(explicit.length)return res.json({rows:explicit,source:'curated'});const fallback=await q(`SELECT rp.id,rp.slug,rp.name,b.name brand_name,CASE WHEN rp.brand_id=p.brand_id THEN 'Related' ELSE 'Cross-sell' END relation_type,0 sort_order FROM products p JOIN products rp ON rp.id<>p.id LEFT JOIN brands b ON b.id=rp.brand_id WHERE p.slug=$1 AND rp.status='Active' AND rp.website_visibility='Published' AND (rp.category_id=p.category_id OR rp.brand_id=p.brand_id) ORDER BY CASE WHEN rp.category_id=p.category_id THEN 0 ELSE 1 END,rp.featured DESC,rp.updated_at DESC LIMIT 12`,[req.params.slug]);res.json({rows:fallback,source:'catalogue'})}catch(e){res.status(503).json({rows:[]})}});
app.get('/api/public/delivery/quote',async(req,res)=>{const region=String(req.query.region||'').trim();if(!region)return res.status(400).json({error:'Delivery region is required.'});try{const rows=await q("SELECT id,name,region,fee,eta_hours FROM delivery_zones WHERE status='Active' AND (lower(region)=lower($1) OR lower(name)=lower($1)) ORDER BY fee LIMIT 1",[region]);const z=rows[0];if(!z)return res.json({available:true,fee:0,etaHours:48,label:'Delivery fee will be confirmed by Amaal before dispatch.'});res.json({available:true,fee:Number(z.fee),etaHours:Number(z.eta_hours),label:z.name})}catch(e){res.status(503).json({error:'Delivery pricing is temporarily unavailable.'})}});
app.get('/api/public/account',async(req,res)=>{const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});try{const orders=await q(`SELECT o.order_no,o.status,o.fulfillment_status,o.grand_total,o.currency,o.shipping_address,o.created_at,d.shipment_no,d.status delivery_status,d.tracking_number FROM orders o LEFT JOIN delivery_shipments d ON d.order_id=o.id WHERE o.customer_id=$1 ORDER BY o.created_at DESC LIMIT 50`,[c.id]);const addresses=await q('SELECT id,label,address_line1,address_line2,city,region,postal_code,country_code,is_default FROM customer_addresses WHERE customer_id=$1 ORDER BY is_default DESC,created_at DESC',[c.id]);const notifications=await q('SELECT id,title,body,created_at,read_at FROM customer_notifications WHERE customer_id=$1 ORDER BY created_at DESC LIMIT 50',[c.id]);res.json({customer:{id:c.id,customerNo:c.customer_no,name:c.name,email:c.email,phone:c.phone,city:c.city,region:c.region},orders,addresses,notifications})}catch(e){res.status(503).json({error:'Your account is temporarily unavailable.'})}});
app.post('/api/public/account/addresses',async(req,res)=>{if(!(await requireCustomerCsrf(req,res)))return;const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});const b=req.body||{};if(!String(b.addressLine1||'').trim()||!String(b.city||'').trim())return res.status(400).json({error:'Address and city are required.'});try{const client=await pool.connect();try{await client.query('BEGIN');if(b.isDefault)await client.query('UPDATE customer_addresses SET is_default=false WHERE customer_id=$1',[c.id]);const a=(await client.query('INSERT INTO customer_addresses(customer_id,label,address_line1,address_line2,city,region,postal_code,country_code,is_default) VALUES($1,$2,$3,$4,$5,$6,$7,\'UG\',$8) RETURNING *',[c.id,String(b.label||'Address').slice(0,80),String(b.addressLine1).slice(0,300),String(b.addressLine2||'').slice(0,300),String(b.city).slice(0,100),String(b.region||'').slice(0,100),String(b.postalCode||'').slice(0,30),Boolean(b.isDefault)])).rows[0];await client.query('COMMIT');res.status(201).json(a)}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}}catch(e){res.status(400).json({error:'Unable to save address.'})}});
app.get('/api/public/account/orders/:orderNo',async(req,res)=>{const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});try{const o=(await q('SELECT id,order_no,status,fulfillment_status,grand_total,currency,shipping_address,created_at FROM orders WHERE order_no=$1 AND customer_id=$2',[req.params.orderNo,c.id]))[0];if(!o)return res.status(404).json({error:'Order not found.'});const lines=await q(`SELECT l.quantity,l.unit_price,l.line_total,v.variant_name,p.name product_name FROM order_lines l JOIN product_variants v ON v.id=l.variant_id JOIN products p ON p.id=v.product_id WHERE l.order_id=$1 ORDER BY l.created_at`,[o.id]);const events=await q('SELECT status,notes,created_at FROM order_status_history WHERE order_id=$1 ORDER BY created_at',[o.id]);const {id,...safeOrder}=o;res.json({order:safeOrder,lines,events})}catch(e){res.status(503).json({error:'Order details are temporarily unavailable.'})}});
app.post('/api/public/account/reorder/:orderNo',async(req,res)=>{if(!(await requireCustomerCsrf(req,res)))return;const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});const client=await pool.connect();try{await client.query('BEGIN');const o=(await client.query('SELECT id FROM orders WHERE order_no=$1 AND customer_id=$2',[req.params.orderNo,c.id])).rows[0];if(!o)throw new Error('Order not found.');const cart=(await client.query("SELECT * FROM commerce_carts WHERE customer_id=$1 AND status='Active' AND expires_at>now() LIMIT 1 FOR UPDATE",[c.id])).rows[0]||(await client.query("INSERT INTO commerce_carts(customer_id,status,currency) VALUES($1,'Active','UGX') RETURNING *",[c.id])).rows[0];const lines=(await client.query(`SELECT ol.variant_id,ol.quantity,v.serialized,v.track_inventory,p.name FROM order_lines ol JOIN product_variants v ON v.id=ol.variant_id JOIN products p ON p.id=v.product_id WHERE ol.order_id=$1`,[o.id])).rows;let added=0,skipped=0;for(const line of lines){const v=await validatePublicCartVariant(client,line.variant_id);const existing=Number((await client.query('SELECT quantity FROM commerce_cart_items WHERE cart_id=$1 AND variant_id=$2',[cart.id,v.id])).rows[0]?.quantity||0);const requested=Math.max(1,Math.min(100,Number(line.quantity)||1));if(v.track_inventory){const available=Number((await client.query('SELECT COALESCE(SUM(on_hand-reserved),0) available FROM inventory_balances WHERE variant_id=$1',[v.id])).rows[0].available||0);if(available<Math.min(100,existing+requested)){skipped++;continue;}}await client.query(`INSERT INTO commerce_cart_items(cart_id,variant_id,quantity) VALUES($1,$2,$3) ON CONFLICT(cart_id,variant_id) DO UPDATE SET quantity=LEAST(100,commerce_cart_items.quantity+EXCLUDED.quantity),updated_at=now()`,[cart.id,v.id,requested]);added++;}await client.query('UPDATE commerce_carts SET updated_at=now(),expires_at=now()+interval \'30 days\' WHERE id=$1',[cart.id]);await client.query('COMMIT');const payload=await publicCartPayload(pool,cart.id);res.json({...payload,added,skipped});}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(400).json({error:e.message||'Unable to reorder this order.'});}finally{client.release();}}
);
app.post('/api/public/account/returns',async(req,res)=>{if(!(await requireCustomerCsrf(req,res)))return;const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});const b=req.body||{};if(!b.orderNo||!Array.isArray(b.lines)||!b.lines.length||!String(b.reason||'').trim())return res.status(400).json({error:'Order, products and return reason are required.'});const client=await pool.connect();try{await client.query('BEGIN');const o=(await client.query("SELECT * FROM orders WHERE order_no=$1 AND customer_id=$2 AND status IN ('Paid','Processing','Packed','Ready for Dispatch','Dispatched','Delivered','Returned') FOR UPDATE",[b.orderNo,c.id])).rows[0];if(!o)throw new Error('Order not found or not eligible for return.');const active=(await client.query("SELECT id FROM return_requests WHERE order_id=$1 AND status NOT IN ('Cancelled','Rejected','Refunded') LIMIT 1",[o.id])).rows[0];if(active)throw new Error('This order already has an active return request.');const no=`WEB-R-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;const r=(await client.query("INSERT INTO return_requests(return_no,customer_id,order_id,reason,notes,refund_method,refund_amount,requested_by) VALUES($1,$2,$3,$4,$5,'Original Payment',0,NULL) RETURNING id,return_no,status,refund_amount,created_at",[no,c.id,o.id,String(b.reason).slice(0,500),String(b.notes||'').slice(0,1000)])).rows[0];let total=0;for(const l of b.lines){const line=(await client.query("SELECT ol.*,v.id variant_id FROM order_lines ol JOIN product_variants v ON v.id=ol.variant_id WHERE ol.id=$1 AND ol.order_id=$2 FOR UPDATE",[l.orderLineId,o.id])).rows[0];if(!line)throw new Error('A return line does not belong to this order.');const qty=Number(l.quantity);if(!Number.isFinite(qty)||qty<=0||qty>Number(line.quantity))throw new Error('Return quantity is invalid.');const prior=Number((await client.query("SELECT COALESCE(sum(rl.quantity),0) q FROM return_lines rl JOIN return_requests rr ON rr.id=rl.return_id WHERE rl.order_line_id=$1 AND rr.status NOT IN ('Cancelled','Rejected')",[line.id])).rows[0].q||0);if(prior+qty>Number(line.quantity)+.0001)throw new Error('Return quantity exceeds the remaining eligible quantity.');const amount=Math.round(Number(line.unit_price)*qty*100)/100;total+=amount;await client.query("INSERT INTO return_lines(return_id,variant_id,order_line_id,quantity,unit_price,reason,condition,disposition,refund_amount) VALUES($1,$2,$3,$4,$5,$6,'Unknown','Restock',$7)",[r.id,line.variant_id,line.id,qty,line.unit_price,String(l.reason||b.reason).slice(0,500),amount]);}await client.query('UPDATE return_requests SET refund_amount=$1 WHERE id=$2',[Math.round(total*100)/100,r.id]);await client.query("INSERT INTO return_events(return_id,status,note,actor_id) VALUES($1,'Requested','Return request created through the Amaal customer account',NULL)",[r.id]);await client.query("INSERT INTO customer_notifications(customer_id,title,body) VALUES($1,'Return request received',$2)",[c.id,`Your return request ${no} has been received by Amaal.`]);await client.query('COMMIT');res.status(201).json({return:{...r,refund_amount:total}})}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(400).json({error:e.message||'Unable to create return request.'})}finally{client.release()}});
app.get('/api/public/account/service',async(req,res)=>{const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});try{const [returns,warranty,repairs]=await Promise.all([q('SELECT return_no,status,refund_amount,created_at,updated_at FROM return_requests WHERE customer_id=$1 ORDER BY created_at DESC LIMIT 30',[c.id]),q('SELECT claim_no,status,warranty_status,issue,resolution,created_at,updated_at FROM warranty_claims WHERE customer_id=$1 ORDER BY created_at DESC LIMIT 30',[c.id]),q(`SELECT r.job_no,r.status,r.diagnosis,r.work_done,r.updated_at,w.claim_no FROM repair_jobs r JOIN warranty_claims w ON w.id=r.claim_id WHERE w.customer_id=$1 ORDER BY r.created_at DESC LIMIT 30`,[c.id])]);res.json({returns,warranty,repairs})}catch(e){res.status(503).json({error:'Service history is temporarily unavailable.'})}});
app.post('/api/public/account/warranty',async(req,res)=>{if(!(await requireCustomerCsrf(req,res)))return;const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});const b=req.body||{};if(!String(b.issue||'').trim())return res.status(400).json({error:'Please describe the issue.'});try{const order=b.orderNo?(await q('SELECT id FROM orders WHERE order_no=$1 AND customer_id=$2',[String(b.orderNo),c.id]))[0]:null;if(b.orderNo&&!order)return res.status(404).json({error:'Order not found.'});const claimNo=`WEB-W-${new Date().toISOString().slice(0,10).replace(/-/g,'')}-${crypto.randomUUID().slice(0,8).toUpperCase()}`;const r=(await q("INSERT INTO warranty_claims(claim_no,customer_id,order_id,variant_id,issue,status,warranty_status,created_by) VALUES($1,$2,$3,$4,$5,'Submitted','Pending',NULL) RETURNING claim_no,status,warranty_status,created_at",[claimNo,c.id,order?.id||null,b.variantId||null,String(b.issue).slice(0,2000)]))[0];await q("INSERT INTO customer_notifications(customer_id,title,body) VALUES($1,'Warranty request received',$2)",[c.id,`Your warranty request ${claimNo} has been received by Amaal.`]);res.status(201).json({claim:r})}catch(e){res.status(400).json({error:'Unable to submit the warranty request.'})}});
app.get('/api/public/account/wishlist',async(req,res)=>{const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});res.json(await q(`SELECT p.id,p.slug,p.name,b.name brand_name FROM customer_wishlist_items w JOIN products p ON p.id=w.product_id LEFT JOIN brands b ON b.id=p.brand_id WHERE w.customer_id=$1 AND p.status='Active' ORDER BY w.created_at DESC`,[c.id]))});
app.post('/api/public/account/wishlist',async(req,res)=>{if(!(await requireCustomerCsrf(req,res)))return;const c=await publicAccountCustomer(req);if(!c)return res.status(401).json({error:'Customer access expired or unavailable.'});const productId=String(req.body?.productId||'');if(!productId)return res.status(400).json({error:'Product is required.'});try{const exists=(await q("SELECT id FROM products WHERE id=$1 AND status='Active'",[productId]))[0];if(!exists)return res.status(404).json({error:'Product not found.'});if(req.body?.saved===false)await q('DELETE FROM customer_wishlist_items WHERE customer_id=$1 AND product_id=$2',[c.id,productId]);else await q('INSERT INTO customer_wishlist_items(customer_id,product_id) VALUES($1,$2) ON CONFLICT DO NOTHING',[c.id,productId]);res.json({saved:req.body?.saved!==false})}catch(e){res.status(400).json({error:'Unable to update saved products.'})}});
