app.post('/api/public/cart/merge',async(req,res)=>{if(!(await requireCustomerCsrf(req,res)))return;const client=await pool.connect();try{await client.query('BEGIN');const customer=await publicAccountCustomer(req);if(!customer)throw new Error('Customer access is required.');const guest=String(req.body?.guestToken||'').trim();const gh=hashGuestCartToken(guest);if(gh){const guestCart=(await client.query("SELECT * FROM commerce_carts WHERE guest_token_hash=$1 AND status='Active' AND expires_at>now() FOR UPDATE",[gh])).rows[0];if(guestCart){const customerCart=(await client.query("SELECT * FROM commerce_carts WHERE customer_id=$1 AND status='Active' FOR UPDATE",[customer.id])).rows[0]|| (await client.query("INSERT INTO commerce_carts(customer_id,status,currency) VALUES($1,'Active','UGX') RETURNING *",[customer.id])).rows[0];const guestItems=(await client.query('SELECT * FROM commerce_cart_items WHERE cart_id=$1',[guestCart.id])).rows;for(const item of guestItems){const existing=(await client.query('SELECT * FROM commerce_cart_items WHERE cart_id=$1 AND variant_id=$2 FOR UPDATE',[customerCart.id,item.variant_id])).rows[0];if(existing)await client.query('UPDATE commerce_cart_items SET quantity=LEAST(100,quantity+$1),updated_at=now() WHERE id=$2',[Number(item.quantity),existing.id]);else await client.query('INSERT INTO commerce_cart_items(cart_id,variant_id,quantity) VALUES($1,$2,$3)',[customerCart.id,item.variant_id,item.quantity]);}await client.query("UPDATE commerce_carts SET status='Converted',updated_at=now() WHERE id=$1",[guestCart.id]);}}const cart=(await client.query("SELECT * FROM commerce_carts WHERE customer_id=$1 AND status='Active' AND expires_at>now() LIMIT 1 FOR UPDATE",[customer.id])).rows[0];await client.query('COMMIT');const payload=cart?await publicCartPayload(pool,cart.id):{cartId:null,items:[],subtotal:0,itemCount:0,currency:'UGX'};res.json(payload);}catch(e){try{await client.query('ROLLBACK')}catch{}res.status(400).json({error:e.message||'Unable to merge your bag.'});}finally{client.release();}
});
app.post('/api/public/commerce/event',async(req,res)=>{try{const c=await publicCustomer(req);const guest=guestCartToken(req);const allowed=new Set(['product_view','result_click','category_view','brand_view','filter','compare','wishlist','add_to_bag','cart_view','checkout_start','checkout_complete','checkout_abandoned','order','tracking_view','return_request','warranty_request','support_request']);const event=String(req.body?.eventType||'').trim();if(!allowed.has(event))return res.status(400).json({error:'Unsupported commerce event.'});await q('INSERT INTO commerce_events(customer_id,guest_key,event_type,product_id,variant_id,query,metadata) VALUES($1,$2,$3,$4,$5,$6,$7)',[c?.id||null,guest?hashGuestCartToken(guest):null,event,req.body?.productId||null,req.body?.variantId||null,String(req.body?.query||'').slice(0,160),JSON.stringify(req.body?.metadata||{})]);res.status(204).end();}catch{res.status(204).end();}});
app.get('/api/public/products/:slug/alerts',async(req,res)=>{try{const p=(await q("SELECT id,name FROM products WHERE slug=$1 AND status='Active' AND website_visibility='Published'",[req.params.slug]))[0];if(!p)return res.status(404).json({error:'Product not found.'});const variants=await q(`SELECT v.sku,v.variant_name,v.color,v.storage,v.size,v.selling_price,CASE WHEN v.track_inventory THEN COALESCE((SELECT SUM(ib.on_hand-ib.reserved) FROM inventory_balances ib WHERE ib.variant_id=v.id),0)>0 ELSE true END in_stock FROM product_variants v WHERE v.product_id=$1 AND v.status='Active' ORDER BY v.sku`,[p.id]);res.json({product:{name:p.name},variants});}catch{res.status(503).json({error:'Availability information is temporarily unavailable.'})}});
app.post('/api/public/products/:slug/price-alert',publicCheckoutLimit,async(req,res)=>{try{const p=(await q("SELECT id,name FROM products WHERE slug=$1 AND status='Active' AND website_visibility='Published'",[req.params.slug]))[0];if(!p)return res.status(404).json({error:'Product not found.'});const c=await publicCustomer(req);const email=String(c?.email||req.body?.email||'').trim().toLowerCase().slice(0,180),phone=String(c?.phone||req.body?.phone||'').trim().slice(0,40);if(!email&&!phone)return res.status(400).json({error:'Email or phone is required.'});const target=req.body?.targetPrice===''||req.body?.targetPrice==null?null:Number(req.body.targetPrice);if(target!==null&&(!Number.isFinite(target)||target<=0))return res.status(400).json({error:'Target price is invalid.'});const r=(await q("INSERT INTO product_price_alerts(customer_id,product_id,email,phone,target_price) VALUES($1,$2,$3,$4,$5) RETURNING id,status,created_at",[c?.id||null,p.id,email,phone,target]))[0];res.status(201).json({alert:r,message:'We will notify you when this product reaches your target price.'});}catch{res.status(503).json({error:'We could not create the price alert.'})}});
app.post('/api/public/products/:slug/back-in-stock',publicCheckoutLimit,async(req,res)=>{try{const p=(await q("SELECT id,name FROM products WHERE slug=$1 AND status='Active' AND website_visibility='Published'",[req.params.slug]))[0];if(!p)return res.status(404).json({error:'Product not found.'});const variantId=String(req.body?.variantId||'').trim();const v=(await q("SELECT id FROM product_variants WHERE id=$1 AND product_id=$2 AND status='Active'",[variantId,p.id]))[0];if(!v)return res.status(400).json({error:'Choose a valid product option.'});const c=await publicCustomer(req);const email=String(c?.email||req.body?.email||'').trim().toLowerCase().slice(0,180),phone=String(c?.phone||req.body?.phone||'').trim().slice(0,40);if(!email&&!phone)return res.status(400).json({error:'Email or phone is required.'});const r=(await q("INSERT INTO product_stock_alerts(customer_id,variant_id,email,phone) VALUES($1,$2,$3,$4) RETURNING id,status,created_at",[c?.id||null,v.id,email,phone]))[0];res.status(201).json({alert:r,message:'We will let you know when this option is back in stock.'});}catch{res.status(503).json({error:'We could not create the stock alert.'})}});
app.post('/api/public/search/save',publicCheckoutLimit,async(req,res)=>{try{const c=await publicCustomer(req);const guest=guestCartToken(req);const query=String(req.body?.query||'').trim().slice(0,160);if(!query)return res.status(400).json({error:'Search query is required.'});if(!c&&!guest)return res.status(401).json({error:'A customer account or guest key is required.'});const r=(await q('INSERT INTO saved_searches(customer_id,guest_key,query,filters) VALUES($1,$2,$3,$4) RETURNING *',[c?.id||null,c?null:hashGuestCartToken(guest),query,JSON.stringify(req.body?.filters||{})]))[0];res.status(201).json(r);}catch{res.status(503).json({error:'We could not save that search.'})}});
app.get('/api/public/search/saved',async(req,res)=>{try{const c=await publicCustomer(req);const guest=guestCartToken(req);if(!c&&!guest)return res.json({rows:[]});const rows=await q('SELECT id,query,filters,status,created_at,updated_at FROM saved_searches WHERE '+(c?'customer_id=$1':'guest_key=$1')+' AND status<>\'Cancelled\' ORDER BY updated_at DESC LIMIT 50',[c?.id||hashGuestCartToken(guest)]);res.json({rows});}catch{res.status(503).json({rows:[]})}});
app.post('/api/public/reviews/:id/helpful',publicCheckoutLimit,async(req,res)=>{try{const review=(await q("SELECT id FROM product_reviews WHERE id=$1 AND status='Published'",[req.params.id]))[0];if(!review)return res.status(404).json({error:'Review not found.'});const voter=String(req.body?.voterKey||req.get('X-Amaal-Guest-Cart-Token')||'').trim();if(!voter)return res.status(400).json({error:'A voter key is required.'});await q('INSERT INTO review_helpful_votes(review_id,voter_key,helpful) VALUES($1,$2,$3) ON CONFLICT(review_id,voter_key) DO UPDATE SET helpful=EXCLUDED.helpful',[review.id,hashGuestCartToken(voter),req.body?.helpful!==false]);const row=(await q('SELECT count(*) FILTER(WHERE helpful)::int helpful,count(*) FILTER(WHERE NOT helpful)::int not_helpful FROM review_helpful_votes WHERE review_id=$1',[review.id]))[0];res.json(row);}catch{res.status(503).json({error:'Unable to record that vote.'})}});

app.post('/api/public/cart/abandoned',publicCheckoutLimit,async(req,res)=>{const b=req.body||{};const email=String(b.email||'').trim().toLowerCase().slice(0,180),phone=String(b.phone||'').trim().slice(0,40);if(!email&&!phone)return res.status(400).json({error:'Email or phone is required to save a bag.'});const rawItems=Array.isArray(b.items)?b.items.slice(0,50):[];if(!rawItems.length)return res.status(400).json({error:'Your bag is empty.'});try{const client=await pool.connect();try{await client.query('BEGIN');const items=[];for(const raw of rawItems){const v=await validatePublicCartVariant(client,String(raw.variantId||raw.id||''));const qty=Math.max(1,Math.min(100,Number(raw.qty||raw.quantity)||1));items.push({variantId:v.id,sku:v.sku,name:v.product_name,quantity:qty,unitPrice:Number(v.selling_price||0)});}const subtotal=Math.round(items.reduce((n,x)=>n+x.unitPrice*x.quantity,0)*100)/100;const r=(await client.query("INSERT INTO abandoned_carts(email,phone,items,subtotal) VALUES($1,$2,$3,$4) RETURNING id,last_seen_at",[email,phone,JSON.stringify(items),subtotal])).rows[0];await client.query('COMMIT');res.status(201).json({saved:true,id:r.id,subtotal});}catch(e){await client.query('ROLLBACK');throw e}finally{client.release()}}catch(e){res.status(400).json({error:e.message||'We could not save your bag right now.'})}});

// Public commerce discovery, trust and merchandising. Read-only catalogue exposure; writes are moderated.
app.get('/api/public/products/:slug/reviews',async(req,res)=>{
  try{
    const product=(await q("SELECT id,name FROM products WHERE slug=$1 AND status='Active' AND website_visibility='Published'",[req.params.slug]))[0];
    if(!product)return res.status(404).json({error:'Product not found.'});
    const summary=(await q("SELECT count(*)::int count,COALESCE(round(avg(rating),1),0)::numeric average FROM product_reviews WHERE product_id=$1 AND status='Published'",[product.id]))[0];
    const rows=await q("SELECT r.id,r.customer_name,r.rating,r.title,r.body,r.verified_purchase,r.created_at,COALESCE((SELECT count(*) FROM review_helpful_votes v WHERE v.review_id=r.id AND v.helpful),0)::int helpful_count FROM product_reviews r WHERE r.product_id=$1 AND r.status='Published' ORDER BY r.created_at DESC LIMIT 50",[product.id]);
    res.json({summary,rows});
  }catch(e){res.status(503).json({error:'Reviews are temporarily unavailable.'})}
});
app.post('/api/public/products/:slug/reviews',publicCheckoutLimit,async(req,res)=>{
  const b=req.body||{}; const customer=await publicCustomer(req); const name=String(customer?.name||b.name||'').trim(), email=String(customer?.email||b.email||'').trim(), body=String(b.body||'').trim();
  const rating=Number(b.rating); if(!name||!body||![1,2,3,4,5].includes(rating))return res.status(400).json({error:'Name, review and a rating from 1 to 5 are required.'});
  try{
    const product=(await q("SELECT id FROM products WHERE slug=$1 AND status='Active' AND website_visibility='Published'",[req.params.slug]))[0]; if(!product)return res.status(404).json({error:'Product not found.'});
    let orderId=null,verified=false;
    const orderNo=String(b.orderNo||'').trim(),phone=String(b.phone||'').trim();
    if(customer&&!orderNo){const delivered=(await q("SELECT o.id FROM orders o JOIN order_lines ol ON ol.order_id=o.id JOIN product_variants v ON v.id=ol.variant_id WHERE o.customer_id=$1 AND o.status='Delivered' AND v.product_id=$2 ORDER BY o.created_at DESC LIMIT 1",[customer.id,product.id]))[0];if(delivered){orderId=delivered.id;verified=true;}}
    if(orderNo&&phone){const o=(await q("SELECT id FROM orders WHERE order_no=$1 AND regexp_replace(shipping_phone,'[^0-9+]','','g')=regexp_replace($2,'[^0-9+]','','g') AND status='Delivered'",[orderNo,phone]))[0]; if(o){const line=(await q("SELECT ol.id FROM order_lines ol JOIN product_variants v ON v.id=ol.variant_id WHERE ol.order_id=$1 AND v.product_id=$2 LIMIT 1",[o.id,product.id]))[0];if(line){orderId=o.id;verified=true;}}}
    if(orderId){const prior=(await q("SELECT id FROM product_reviews WHERE product_id=$1 AND order_id=$2 LIMIT 1",[product.id,orderId]))[0];if(prior)return res.status(409).json({error:'A review for this product has already been submitted for that order.'});}
    const r=(await q("INSERT INTO product_reviews(product_id,order_id,customer_name,customer_email,rating,title,body,verified_purchase,status) VALUES($1,$2,$3,$4,$5,$6,$7,$8,'Pending') RETURNING id,status,created_at",[product.id,orderId,name,email,rating,String(b.title||'').trim(),body,verified]))[0];
    res.status(201).json({review:r,message:'Thanks. Your review has been sent for approval.'});
  }catch(e){res.status(503).json({error:'We could not submit the review right now.'})}
});
