async function runPredefinedOperationsTasks(){
 const client=await pool.connect();
 let rows=[];
 try{
  await client.query('BEGIN');
  rows=(await client.query("SELECT * FROM operations_scheduled_tasks WHERE enabled=true AND next_run_at<=now() ORDER BY next_run_at FOR UPDATE SKIP LOCKED LIMIT 10")).rows;
  for(const task of rows){
   await client.query("UPDATE operations_scheduled_tasks SET next_run_at=now()+(cadence_minutes*interval '1 minute'),last_run_at=now(),updated_at=now() WHERE id=$1",[task.id]);
  }
  await client.query('COMMIT');
 }catch(e){try{await client.query('ROLLBACK')}catch{}console.error('Scheduled operations claim failed:',e.message);return}finally{client.release()}
 for(const task of rows){
  const started=Date.now();
  try{
   if(task.task_key==='backup-daily'&&app.locals.runScheduledBackup) await app.locals.runScheduledBackup();
   else if(task.task_key==='backup-retention'&&app.locals.applyScheduledBackupRetention) await app.locals.applyScheduledBackupRetention();
   else if(task.task_key==='reservation-expiry') await releaseExpiredReservations();
   else if(task.task_key==='operations-health') await pool.query("INSERT INTO operations_events(event_type,severity,detail) VALUES('OPERATIONS_HEARTBEAT','info','Scheduled operations heartbeat completed')");
   else if(task.task_key==='audit-retention-review') await pool.query("INSERT INTO operations_events(event_type,severity,detail) VALUES('AUDIT_RETENTION_REVIEW','info','Audit retention review task completed')");
   await pool.query("UPDATE operations_scheduled_tasks SET failure_count=0,last_duration_ms=$1 WHERE id=$2",[Date.now()-started,task.id]);
  }catch(e){
   await pool.query("UPDATE operations_scheduled_tasks SET failure_count=failure_count+1,last_duration_ms=$1 WHERE id=$2",[Date.now()-started,task.id]);
   await pool.query("INSERT INTO operations_events(event_type,severity,detail,metadata_json) VALUES('SCHEDULED_TASK_FAILED','warning',$1,$2::jsonb)",[`Scheduled task ${task.task_key} failed`,JSON.stringify({taskKey:task.task_key,error:String(e.message||e)})]);
  }
 }
}
init().then(()=>{setInterval(()=>releaseExpiredReservations().catch(e=>console.error(e)),60000).unref();setInterval(()=>runPredefinedOperationsTasks().catch(e=>console.error(e)),60000).unref();app.listen(process.env.PORT||4000,()=>console.log(`Amaal Admin listening on ${process.env.PORT||4000}`))}).catch(e=>{console.error(e);process.exit(1)});
